    #[test]
    fn independently_encoded_recursive_circles_map_all_coincident_half_relations() {
        // Counterclockwise quarter turn about the retained rational center
        // (0,-1): translation is C-RC=(-1,-1).
        let third = (Real::one() / Real::from(3_i8)).unwrap();
        let two_thirds = (Real::from(2_i8) / Real::from(3_i8)).unwrap();
        let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
        let quarter_turn = Similarity2::try_from_real_affine(
            Real::zero(),
            Real::from(-1_i8),
            Real::one(),
            Real::zero(),
            Real::from(-1_i8),
            Real::from(-1_i8),
        )
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = recursively_pair_radial_rational_center_half(&policy);
            let aligned = recursively_pair_radial_rational_center_half(&policy);
            for (second, expected_orientation) in [
                (aligned.clone(), RationalBezierOverlapOrientation2::Same),
                (
                    aligned.reversed(),
                    RationalBezierOverlapOrientation2::Reversed,
                ),
            ] {
                for (left, right) in [(&first, &second), (&second, &first)] {
                    let result = left.pair_intersections(right, &policy).unwrap();
                    let Classification::Decided(
                        BezierAlgebraicCuspSemicirclePairIntersections2::Overlap(overlap),
                    ) = result
                    else {
                        panic!("independent recursive aligned halves must overlap: {result:?}");
                    };
                    assert!(overlap.has_exact_endpoint_map());
                    assert_eq!(overlap.orientation(), expected_orientation);
                }
            }

            let complementary =
                recursively_pair_radial_rational_center_half(&policy).complementary_half();
            for (left, right) in [(&first, &complementary), (&complementary, &first)] {
                let result = left.pair_intersections(right, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::EndpointContacts(contacts),
                ) = result
                else {
                    panic!(
                        "independent recursive complementary halves must meet at endpoints: {result:?}"
                    );
                };
                assert_eq!(contacts.len(), 2);
            }

            let partial = recursively_pair_radial_rational_center_half(&policy)
                .transform_similarity(&quarter_turn)
                .unwrap();
            for (second, expected_orientation) in [
                (partial.clone(), RationalBezierOverlapOrientation2::Same),
                (
                    partial.reversed(),
                    RationalBezierOverlapOrientation2::Reversed,
                ),
            ] {
                for (left, right) in [(&first, &second), (&second, &first)] {
                    let result = left.pair_intersections(right, &policy).unwrap();
                    let Classification::Decided(
                        BezierAlgebraicCuspSemicirclePairIntersections2::Overlap(overlap),
                    ) = result
                    else {
                        panic!(
                            "independent recursive turned halves must partially overlap: {result:?}"
                        );
                    };
                    assert!(!overlap.has_exact_endpoint_map());
                    assert_eq!(overlap.orientation(), expected_orientation);
                    for parameter in [
                        overlap.first_start_parameter(),
                        overlap.first_end_parameter(),
                        overlap.second_start_parameter(),
                        overlap.second_end_parameter(),
                    ] {
                        assert!(matches!(
                            parameter.parameter_bracket(16, &policy).unwrap(),
                            Classification::Decided(_)
                        ));
                    }
                    let (source, target) = if left == &first {
                        (
                            three_quarters.clone(),
                            if expected_orientation == RationalBezierOverlapOrientation2::Same {
                                third.clone()
                            } else {
                                two_thirds.clone()
                            },
                        )
                    } else {
                        (
                            if expected_orientation == RationalBezierOverlapOrientation2::Same {
                                third.clone()
                            } else {
                                two_thirds.clone()
                            },
                            three_quarters.clone(),
                        )
                    };
                    let mapped = overlap.map_parameter(
                        &BezierAlgebraicCuspSemicircleParameter2::Exact(source.clone()),
                        true,
                    );
                    assert_eq!(
                        mapped.order_to_real(&target, &policy).unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal),
                    );
                    assert_eq!(
                        overlap
                            .map_parameter(&mapped, false)
                            .cmp_by_refinement(
                                &BezierAlgebraicCuspSemicircleParameter2::Exact(source),
                                &policy,
                            )
                            .unwrap(),
                        Classification::Decided(std::cmp::Ordering::Equal),
                    );
                }
            }
        }
    }

    #[test]
    fn pair_radial_authored_tangency_survives_scaled_reflection() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let reflection = Similarity2::try_from_real_affine(
            Real::from(-3_i8),
            Real::zero(),
            Real::zero(),
            Real::from(3_i8),
            Real::from(2_i8),
            Real::from(3_i8),
        )
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let authored = independent_pair_radial_unit_circle(&policy);
            let parent = match authored.selected_radial_frame_source(&policy).unwrap() {
                Classification::Decided(source) => source.pair_map.data.first_semicircle.clone(),
                Classification::Uncertain(reason) => {
                    panic!("the pair-radial author must remain available: {reason:?}")
                }
            };
            let Classification::Decided(Some(child)) =
                authored.scaled_radial_distance(&half, &policy).unwrap()
            else {
                panic!("the pair-radial child must retain its half radius");
            };
            let child = child.complementary_half();
            let Classification::Decided(Some(parent)) =
                parent.scaled_radial_distance(&half, &policy).unwrap()
            else {
                panic!("the parent support must retain its half radius");
            };
            let reflected_child = child.transform_similarity(&reflection).unwrap();
            let reflected_parent = parent.transform_similarity(&reflection).unwrap();

            let classify = |first: &BezierAlgebraicCuspSemicircle2,
                            second: &BezierAlgebraicCuspSemicircle2| {
                let result = first.pair_intersections(second, &policy).unwrap();
                let Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                        contacts,
                        parameter_map,
                    },
                ) = result
                else {
                    panic!("the authored external tangency must remain exact: {result:?}");
                };
                let [contact] = contacts.as_slice() else {
                    panic!("the authored external tangency must retain one contact: {contacts:?}");
                };
                assert_eq!(contact.branch, 0);
                assert_eq!(contact.tangent_cross_sign, RealSign::Zero);
                let Classification::Decided(tangent_dot) =
                    parameter_map.tangent_dot_sign(contact, &policy).unwrap()
                else {
                    panic!("the authored tangent direction must be decided");
                };
                let Classification::Decided([x, y]) = parameter_map
                    .represented_selected_radial_contact_point(contact)
                    .unwrap()
                else {
                    panic!("the authored tangent point must remain represented exactly");
                };
                assert!(x.is_valid() && y.is_valid());
                (contact.first_location, contact.second_location, tangent_dot)
            };

            let direct = classify(&child, &parent);
            let reflected = classify(&reflected_child, &reflected_parent);
            assert_eq!(reflected, direct);
            let reflected_reversed = classify(&reflected_parent, &reflected_child);
            assert_eq!(
                reflected_reversed,
                (direct.1, direct.0, direct.2),
                "pair order may swap the parameters but not the tangent relation"
            );
        }
    }

    #[test]
    fn recursively_pair_radial_circles_handle_tangent_and_disjoint_supports() {
        let translate = |distance: Real| {
            Similarity2::try_from_real_affine(
                Real::one(),
                Real::zero(),
                Real::zero(),
                Real::one(),
                distance,
                Real::zero(),
            )
            .unwrap()
        };
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let first = recursively_pair_radial_half(&policy);
            let tangent = first
                .transform_similarity(&translate(Real::one()))
                .unwrap()
                .complementary_half();
            let result = first.pair_intersections(&tangent, &policy).unwrap();
            let Classification::Decided(
                BezierAlgebraicCuspSemicirclePairIntersections2::Contacts {
                    contacts,
                    parameter_map,
                },
            ) = result
            else {
                panic!("the recursive tangent pair must complete exactly: {result:?}");
            };
            let [contact] = contacts.as_slice() else {
                panic!("the recursive tangent pair must retain one contact: {contacts:?}");
            };
            assert_eq!(contact.branch, 0);
            assert_eq!(
                contact.first_location,
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_eq!(
                contact.second_location,
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_eq!(contact.tangent_cross_sign, RealSign::Zero);
            assert_eq!(
                parameter_map.tangent_dot_sign(contact, &policy).unwrap(),
                Classification::Decided(RealSign::Negative),
            );
            let Classification::Decided([x, y]) = parameter_map
                .represented_selected_radial_contact_point(contact)
                .unwrap()
            else {
                panic!("the recursive tangency must retain exact coordinates");
            };
            assert!(
                compare_reals(&x.interval.lower, &Real::one(), &CurveContext::STRICT)
                    != Some(std::cmp::Ordering::Greater)
                    && compare_reals(&x.interval.upper, &Real::one(), &CurveContext::STRICT)
                        != Some(std::cmp::Ordering::Less)
            );
            assert_eq!(
                compare_reals(&y.interval.upper, &Real::zero(), &CurveContext::STRICT),
                Some(std::cmp::Ordering::Less),
            );

            let disjoint = first
                .transform_similarity(&translate(Real::from(2_i8)))
                .unwrap()
                .complementary_half();
            assert!(matches!(
                first.pair_intersections(&disjoint, &policy).unwrap(),
                Classification::Decided(
                    BezierAlgebraicCuspSemicirclePairIntersections2::NoContacts
                ),
            ));
        }
    }

