    #[test]
    fn selected_third_axis_incident_domain_stops_before_the_regular_barrier() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            for (coefficients, anchor, direction, barrier, expected) in [
                (
                    vec![Real::from(6_i8), Real::from(-5_i8), Real::one()],
                    Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    (Real::from(5_i8) / Real::from(2_i8)).unwrap(),
                    Real::from(2_i8),
                ),
                (
                    vec![Real::from(2_i8), Real::from(3_i8), Real::one()],
                    Real::zero(),
                    BezierParameterRayDirection2::Decreasing,
                    (-Real::from(3_i8) / Real::from(2_i8)).unwrap(),
                    Real::from(-1_i8),
                ),
            ] {
                let Classification::Decided(polynomial) =
                    BezierParameterPolynomial::try_new_power_basis(coefficients, &policy).unwrap()
                else {
                    panic!("the exact quadratic projection must construct");
                };
                let barrier = BezierParameter2::Exact(barrier);
                let Classification::Decided(parameters) = (SelectedThirdAxisDomain2::IncidentRay {
                    anchor: &anchor,
                    direction,
                    barrier: Some(&barrier),
                })
                .isolate(&polynomial, &policy)
                .unwrap() else {
                    panic!("the barrier-bounded incident projection must be decided");
                };
                assert_eq!(parameters, vec![BezierParameter2::Exact(expected)]);
            }
        }
    }

    #[test]
    fn procedural_endpoint_chord_replays_complete_parallel_contacts() {
        let parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new((Real::one() / Real::from(2_i8)).unwrap(), Real::zero()),
            Point2::from_values(1, 1),
        )
        .parallel_left(Real::zero())
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let start = RationalBezierIntersectionPointEvidence2::AnalyticParallel(
                BezierAnalyticParallelPoint2::new(
                    parallel.clone(),
                    BezierParameter2::Exact(Real::zero()),
                    &policy,
                ),
            );
            let chord = match BezierAlgebraicChord2::try_new_from_certified_distinct_endpoints(
                start,
                RationalBezierIntersectionPointEvidence2::Exact(Point2::from_values(1, 0)),
                &policy,
            )
            .unwrap()
            {
                Classification::Decided(chord) => chord,
                Classification::Uncertain(reason) => {
                    panic!("the procedural endpoint chord must construct: {reason:?}")
                }
            };
            for chord in [chord.clone(), chord.reversed()] {
                let contacts = match chord.parallel_intersections(&parallel, &policy).unwrap() {
                    Classification::Decided(
                        BezierAlgebraicChordParallelIntersections2::Contacts(contacts),
                    ) => contacts,
                    result => panic!("the procedural chord incidence must decide: {result:?}"),
                };
                let [contact] = contacts.as_slice() else {
                    panic!("the parabola must touch its endpoint chord exactly once")
                };
                assert_eq!(contact.parallel_parameter().as_exact(), Some(&Real::zero()));
                assert_eq!(contact.tangent_cross_sign(), RealSign::Zero);
            }
        }
    }

    #[test]
    fn chord_parallel_extension_keeps_target_and_chord_domains_independent() {
        let parallel = QuadraticBezier2::new(
            Point2::from_values(1, -1),
            Point2::from_values(2, 0),
            Point2::from_values(4, 1),
        )
        .parallel_left(Real::zero())
        .unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let half = (Real::one() / Real::from(2_i8)).unwrap();
            let third = (Real::one() / Real::from(3_i8)).unwrap();
            let BezierParameter2::Algebraic(first_parameter) =
                algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
            else {
                unreachable!("sqrt(1/2) must remain algebraic");
            };
            let BezierParameter2::Algebraic(second_parameter) =
                algebraic_parameter(vec![-third, Real::zero(), Real::one()])
            else {
                unreachable!("sqrt(1/3) must remain algebraic");
            };
            let horizontal = RationalBezier2::try_from_subcurve(&BezierSubcurve2::Quadratic(
                QuadraticBezier2::from_line_segment(
                    LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0))
                        .unwrap(),
                ),
            ))
            .unwrap();
            let start = RationalBezierIntersectionPointEvidence2::Algebraic(
                horizontal
                    .point_at_algebraic_parameter(&first_parameter, &policy)
                    .unwrap(),
            );
            let end = RationalBezierIntersectionPointEvidence2::Algebraic(
                horizontal
                    .point_at_algebraic_parameter(&second_parameter, &policy)
                    .unwrap(),
            );
            let Classification::Decided(chord) =
                BezierAlgebraicChord2::try_new(start, end, &policy).unwrap()
            else {
                panic!("the independent horizontal chord must construct");
            };
            for chord in [chord.clone(), chord.reversed()] {
                let finite = match chord.parallel_intersections(&parallel, &policy).unwrap() {
                    Classification::Decided(
                        BezierAlgebraicChordParallelIntersections2::Contacts(finite),
                    ) => finite,
                    result => panic!("the finite chord relation must be decided: {result:?}"),
                };
                assert!(finite.is_empty());

                let Classification::Decided(BezierAlgebraicChordParallelIntersections2::Contacts(
                    extended,
                )) = chord
                    .parallel_intersections_with_incident_ray(
                        &parallel,
                        &incident_domain(
                            &parallel,
                            Real::one(),
                            BezierParameterRayDirection2::Increasing,
                            &policy,
                        ),
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the affine chord-support relation must be decided");
                };
                let [contact] = extended.as_slice() else {
                    panic!("only the finite-target/chord-extension contact must survive");
                };
                assert_eq!(contact.parallel_parameter().as_exact(), Some(&half));
            }
        }
    }

    #[test]
    fn incident_source_circle_stops_at_the_first_projective_pole() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let increasing = RationalBezier2::try_new(
                vec![Point2::from_values(0, 0), Point2::from_values(1, 0)],
                vec![Real::one(), half.clone()],
            )
            .unwrap()
            .parallel_left(Real::zero())
            .unwrap();
            let one_third = (Real::one() / Real::from(3_i8)).unwrap();
            let three_halves = (Real::from(3_i8) / Real::from(2_i8)).unwrap();
            let decreasing = RationalBezier2::try_new(
                vec![
                    Point2::from_values(0, 0),
                    Point2::new(one_third, Real::zero()),
                ],
                vec![Real::one(), three_halves],
            )
            .unwrap()
            .parallel_left(Real::zero())
            .unwrap();
            for (parallel, center, anchor, direction, expected) in [
                (
                    increasing,
                    Point2::from_values(1, 0),
                    Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    (Real::from(8_i8) / Real::from(5_i8)).unwrap(),
                ),
                (
                    decreasing,
                    Point2::from_values(0, 0),
                    Real::zero(),
                    BezierParameterRayDirection2::Decreasing,
                    (-Real::from(3_i8) / Real::from(2_i8)).unwrap(),
                ),
            ] {
                let Classification::Decided(parameters) = parallel
                    .source_circle_incidence_on_incident_ray(
                        &center,
                        &Real::from(9_i8),
                        &anchor,
                        direction,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the pole-partitioned incident ray must be decided");
                };
                let [parameter] = parameters.as_slice() else {
                    panic!("only the contact before the first pole belongs to the incident cell");
                };
                assert_eq!(parameter.as_exact(), Some(&expected));
            }
        }
    }

