    #[test]
    fn radical_component_saturation_retains_norm_intersections() {
        let t = BivariatePolynomial::new(vec![vec![Real::zero()], vec![Real::one()]]);
        let u = BivariatePolynomial::new(vec![vec![Real::zero(), Real::one()]]);
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let common = bivariate_subtract(&bivariate_multiply(&t, &t), &bivariate_multiply(&u, &u));
        let first_residual =
            bivariate_add(&t, &BivariatePolynomial::new(vec![vec![-half.clone()]]));
        let second_residual =
            bivariate_add(&u, &BivariatePolynomial::new(vec![vec![-half.clone()]]));
        let equations = [
            bivariate_multiply(&common, &first_residual),
            bivariate_multiply(&common, &second_residual),
        ];
        let norm = bivariate_add(
            &bivariate_multiply(&common, &common),
            &bivariate_subtract(&t, &BivariatePolynomial::new(vec![vec![half]])),
        );
        let zero = BivariatePolynomial::new(vec![vec![Real::zero()]]);
        let system = BezierParallelPairEquationSystem2 {
            first_equation: equations[0].clone(),
            second_equation: equations[1].clone(),
            norm_equation: norm,
            first_projection: zero.clone(),
            second_projection: zero.clone(),
            tangent_cross: zero.clone(),
            tangent_dot: zero.clone(),
            norm_residual: zero.clone(),
            first_normal_projection: zero,
            first_distance: Real::one(),
            second_distance: Real::one(),
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_sign: RealSign::Positive,
        };
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        let saturation = parallel_pair_saturation_from_equations(&system, equations, config);
        let Classification::Decided(saturation) = saturation else {
            panic!("the exact common support must saturate");
        };
        for (residual, expected) in saturation
            .residual_equations
            .iter()
            .zip([first_residual, second_residual].iter())
        {
            assert!(divide_bivariate_polynomial_exact(residual, expected).is_some());
            assert!(divide_bivariate_polynomial_exact(expected, residual).is_some());
        }
        let [support, norm] = saturation
            .radical_component_equations
            .expect("the removed radical support must be replayed against the norm");
        assert!(divide_bivariate_polynomial_exact(&support, &common).is_some());
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let pairs =
                match bivariate_system_unit_square_solution_pairs(&support, &norm, &policy, config)
                    .unwrap()
                {
                    Classification::Decided(pairs) => pairs,
                    Classification::Uncertain(reason) => {
                        panic!("radical component/norm replay: {reason:?}")
                    }
                };
            assert!(
                !pairs.is_empty(),
                "the removed support/norm intersection must retain a candidate"
            );
            assert!(pairs.iter().any(|pair| {
                signed_bivariate_at_parameter_pair(
                    &support,
                    &pair.parallel_parameter,
                    &pair.other_parameter,
                    &policy,
                )
                .unwrap()
                    == Classification::Decided(RealSign::Zero)
                    && signed_bivariate_at_parameter_pair(
                        &norm,
                        &pair.parallel_parameter,
                        &pair.other_parameter,
                        &policy,
                    )
                    .unwrap()
                        == Classification::Decided(RealSign::Zero)
            }));
        }
    }

    #[test]
    fn selected_structural_parallel_overlap_replays_off_diagonal_contacts() {
        let point = |x, y| Point2::new(Real::from(x), Real::from(y));
        let source = CubicBezier2::new(point(0, 0), point(1, 4), point(3, -4), point(4, 0));
        let distance = (Real::one() / Real::from(2_u8)).unwrap();
        let parallel = source.parallel_left(distance).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let system =
                match parallel_pair_equation_system(&parallel, &parallel, true, &policy).unwrap() {
                    Classification::Decided(Some(system)) => system,
                    _ => panic!("the structural pair system must be decided"),
                };
            let overlap = structural_parallel_overlap(&parallel, &parallel, &policy)
                .unwrap()
                .expect("identical parallels have a structural overlap");
            let selected = Classification::Decided(CertifiedParallelSourceOverlap2 {
                kind: CertifiedParallelSourceOverlapKind2::Selected(overlap),
                contacts: Arc::from([]),
            });
            let projection = project_parallel_pair_without_components(
                &system, &parallel, &parallel, &selected, false, &policy,
            )
            .unwrap()
            .expect("the identity component must leave a finite residual projection");
            let result = match parallel
                .replay_parallel_pair_projection(&parallel, &system, projection, false, &policy)
                .unwrap()
            {
                Classification::Decided(result) => result,
                Classification::Uncertain(reason) => {
                    panic!("selected overlap residual replay: {reason:?}")
                }
            };
            assert!(result.is_complete(), "{result:?}");
            assert_eq!(result.overlaps().len(), 1, "{result:?}");
            assert_eq!(result.contacts().len(), 2, "{result:?}");
        }
    }

    #[test]
    fn incident_source_component_with_unequal_distances_retains_its_residual_system() {
        let first = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new((Real::one() / Real::from(2_i8)).unwrap(), Real::zero()),
            Point2::from_values(1, 1),
        )
        .parallel_left((Real::one() / Real::from(2_i8)).unwrap())
        .unwrap();
        let second = QuadraticBezier2::new(
            Point2::from_values(1, 1),
            Point2::new(
                (Real::from(3_i8) / Real::from(2_i8)).unwrap(),
                Real::from(2_i8),
            ),
            Point2::from_values(2, 4),
        )
        .parallel_left(Real::one())
        .unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let incident = match first
                .parallel_intersections_with_incident_rays(
                    &second,
                    &incident_domain(
                        &first,
                        Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    ),
                    &incident_domain(
                        &second,
                        Real::zero(),
                        BezierParameterRayDirection2::Decreasing,
                        &policy,
                    ),
                    &policy,
                )
                .unwrap()
            {
                Classification::Decided(incident) => incident,
                Classification::Uncertain(reason) => {
                    panic!("excluded incident source component remained uncertain: {reason:?}")
                }
            };
            let (intersections, positive_dimensional) = incident.into_parts();
            assert!(!positive_dimensional);
            assert!(intersections.is_complete(), "{intersections:?}");
        }
    }

    #[test]
    fn exact_rational_parallel_self_intersections_reuse_rational_authority() {
        let point = |x, y| Point2::new(Real::from(x), Real::from(y));
        let loop_controls = vec![point(9, 0), point(-7, 3), point(-7, -10), point(9, 9)];
        let sources = [
            RationalBezier2::try_new(loop_controls.clone(), vec![Real::one(); 4]).unwrap(),
            RationalBezier2::try_new(
                loop_controls,
                vec![
                    Real::one(),
                    Real::from(2_i8),
                    Real::from(4_i8),
                    Real::from(8_i8),
                ],
            )
            .unwrap(),
            RationalBezier2::try_new(
                vec![point(3, 0), point(-5, 1), point(-5, -6), point(3, 3)],
                vec![Real::one(); 4],
            )
            .unwrap(),
        ];

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            for source in &sources {
                let parallel = source.parallel_left(Real::zero()).unwrap();
                let result = match parallel.self_intersections(&policy).unwrap() {
                    Classification::Decided(result) => result,
                    Classification::Uncertain(reason) => {
                        panic!("exact rational self-contact remained uncertain: {reason:?}")
                    }
                };
                assert!(result.is_complete());
                let [contact] = result.contacts() else {
                    panic!("the rational loop must retain one off-diagonal self-contact")
                };
                assert!(contact.is_certified_transverse());
                assert_eq!(contact.tangent_cross_sign(), Some(RealSign::Negative));
                assert!(matches!(
                    contact.tangent_dot_sign(),
                    Some(RealSign::Positive | RealSign::Negative)
                ));
            }
        }
    }

    fn direct_parallel_pair_branch(
        first: &BezierParallel2,
        second: &BezierParallel2,
        policy: &CurveContext,
    ) -> Classification<bool> {
        let Classification::Decided(Some(system)) =
            parallel_pair_equation_system(first, second, true, policy).unwrap()
        else {
            panic!("parallel-pair equation system was not decided");
        };
        let parameter = BezierParameter2::Exact(Real::zero());
        for equation in [
            &system.first_equation,
            &system.second_equation,
            &system.norm_equation,
        ] {
            assert_eq!(
                signed_bivariate_at_parameter_pair(equation, &parameter, &parameter, policy)
                    .unwrap(),
                Classification::Decided(RealSign::Zero)
            );
        }
        parallel_pair_selected_branch(
            &system,
            &parameter,
            &parameter,
            BivariateParameterPairReplay::Direct,
            &[None, None],
            BivariateParameterPairReplay::Direct,
            &[None, None],
            false,
            policy,
        )
        .unwrap()
    }

    #[test]
    fn parallel_pair_tangent_replay_selects_norm_magnitude_and_direction() {
        let source = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(1, 0),
            Point2::from_values(2, 1),
        );
        let first = source.parallel_left(Real::from(3_i8)).unwrap();
        let translated = |height| {
            QuadraticBezier2::new(
                Point2::from_values(0, height),
                Point2::from_values(1, height),
                Point2::from_values(2, height + 1),
            )
            .parallel_left(Real::one())
            .unwrap()
        };
        let selected = translated(2);
        let wrong_norm_magnitude = translated(4);
        let wrong_normal_direction = translated(-2);

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert_eq!(
                direct_parallel_pair_branch(&first, &selected, &policy),
                Classification::Decided(true)
            );
            assert_eq!(
                direct_parallel_pair_branch(&first, &wrong_norm_magnitude, &policy),
                Classification::Decided(false)
            );
            assert_eq!(
                direct_parallel_pair_branch(&first, &wrong_normal_direction, &policy),
                Classification::Decided(false)
            );
        }
    }

