    #[test]
    fn selected_parallel_normal_circle_uses_direct_exact_winding() {
        let support = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let half = (Real::one() / Real::from(2_i8)).unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Exact(half.clone()),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("a regular selected line frame must construct");
            };
            let fragment = BezierAlgebraicCuspSemicircleFragment2::full(circle, &policy);
            assert_eq!(
                fragment
                    .contains_point(&Point2::from_values(0, 0), &policy)
                    .unwrap(),
                Classification::Decided(true),
            );
            assert_eq!(
                fragment
                    .contains_point(&Point2::from_values(2, 0), &policy)
                    .unwrap(),
                Classification::Decided(false),
            );
            assert_eq!(
                fragment
                    .contains_point(&Point2::from_values(1, 0), &policy)
                    .unwrap(),
                Classification::Decided(false),
            );
            assert_eq!(
                fragment
                    .forward_ray_winding_delta(
                        &Point2::from_values(-2, 0),
                        &Real::one(),
                        &Real::zero(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(-1),
            );
            assert_eq!(
                fragment
                    .forward_ray_winding_delta(
                        &Point2::from_values(2, 0),
                        &Real::one(),
                        &Real::zero(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(0),
            );
            assert_eq!(
                fragment
                    .forward_ray_winding_delta(
                        &Point2::from_values(0, 0),
                        &Real::one(),
                        &Real::zero(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Uncertain(UncertaintyReason::Boundary),
            );
            assert_eq!(
                fragment
                    .reversed()
                    .forward_ray_winding_delta(
                        &Point2::from_values(-2, 0),
                        &Real::one(),
                        &Real::zero(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(1),
            );
        }
    }

    #[test]
    fn selected_parallel_contact_map_orders_the_exact_angular_parameter() {
        let anchor = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let contact = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, -1), Point2::from_values(0, 1)).unwrap(),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = &half + &quarter;

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    anchor.clone(),
                    BezierParameter2::Exact(half.clone()),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected line-normal frame must construct");
            };
            let Classification::Decided(parameter) = circle
                .certified_selected_parallel_contact_parameter(
                    contact.clone(),
                    BezierParameter2::Exact(half.clone()),
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                    RealSign::Positive,
                    RealSign::Positive,
                    RealSign::Zero,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the quarter-turn contact must retain an angular map");
            };
            assert_eq!(
                parameter.order_to_real(&quarter, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
            assert_eq!(
                parameter.order_to_real(&half, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                parameter.order_to_real(&three_quarters, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
            let Classification::Decided(Some(contact_point)) = parameter
                .coincident_point_evidence(&circle, &policy)
                .unwrap()
            else {
                panic!("the angular map must replay its analytic contact point");
            };
            let Classification::Decided(circle_point) =
                circle.point_evidence_at(&half, &policy).unwrap()
            else {
                panic!("the represented quarter-turn circle point must be exact");
            };
            for point in [&contact_point, &circle_point] {
                let Classification::Decided(bounds) =
                    algebraic_chord_endpoint_bounds_refined(point, 0, &policy)
                else {
                    panic!("the represented line-frame contact must have exact bounds");
                };
                assert_eq!(bounds.min(), &Point2::from_values(0, 0));
                assert_eq!(bounds.max(), &Point2::from_values(0, 0));
            }
            let Classification::Decided(bracket) = parameter.parameter_bracket(8, &policy).unwrap()
            else {
                panic!("the exact angular contact must refine to a bracket");
            };
            let (start, end) = cusp_semicircle_parameter_bracket_bounds(&bracket);
            assert!(compare_reals(start, &half, &policy) != Some(std::cmp::Ordering::Greater));
            assert!(compare_reals(end, &half, &policy) != Some(std::cmp::Ordering::Less));
        }
    }

    #[test]
    fn selected_parallel_normal_circle_intersects_rational_curves_exactly() {
        let source = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(1, 0),
            Point2::from_values(2, 1),
        );
        let center_support = source.parallel_left(Real::one()).unwrap();
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let root_five = Real::from(5_i8).sqrt().unwrap();
        let inverse_speed = (Real::one() / root_five).unwrap();
        let center_x = Real::one() - &inverse_speed;
        let center_y = &quarter + Real::from(2_i8) * &inverse_speed;
        let cutter = RationalBezier2::try_new(
            vec![
                Point2::new(&center_x - Real::from(2_i8), center_y.clone()),
                Point2::new(&center_x + Real::from(2_i8), center_y.clone()),
            ],
            vec![Real::one(), Real::one()],
        )
        .unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    center_support.clone(),
                    BezierParameter2::Exact(half.clone()),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the non-PH selected circle must construct");
            };
            let Classification::Decided((
                BezierAlgebraicCuspSemicircleRationalIntersections2::Contacts(contacts),
                Some(parameter_map),
            )) = circle
                .rational_intersections_with_parameter_map(&cutter, &policy)
                .unwrap()
            else {
                panic!("the general selected circle must retain its rational contact");
            };
            assert_eq!(contacts.len(), 1);
            let contact = &contacts[0];
            assert_eq!(
                contact
                    .other_parameter
                    .same_value(&BezierParameter2::Exact(quarter.clone()), &policy)
                    .unwrap(),
                Classification::Decided(true),
            );
            assert_eq!(
                contact.location,
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_eq!(contact.tangent_cross_sign, RealSign::Positive);
            assert_eq!(
                contact.point.same_point(
                    &RationalBezierIntersectionPointEvidence2::Exact(Point2::new(
                        &center_x - Real::one(),
                        center_y.clone(),
                    )),
                    &policy,
                ),
                Classification::Decided(true),
            );
            let parameter = parameter_map.contact_parameter(contact);
            assert_eq!(
                parameter.order_to_real(&half, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
            let Classification::Decided(Some(mapped_point)) = parameter
                .coincident_point_evidence(&circle, &policy)
                .unwrap()
            else {
                panic!("the mapped rational contact must retain its exact point");
            };
            assert_eq!(
                mapped_point.same_point(&contact.point, &policy),
                Classification::Decided(true),
            );
        }
    }

    #[test]
    fn selected_parallel_normal_circle_retains_general_rational_contacts_in_one_fiber() {
        let support = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let cutter = RationalBezier2::try_new(
            vec![
                Point2::from_values(-1, 0),
                Point2::from_values(1, 0),
                Point2::from_values(3, 0),
            ],
            vec![Real::one(), Real::one(), Real::one()],
        )
        .unwrap();
        let independent_parallel = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::zero(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the algebraic selected circle must construct");
            };
            let Classification::Decided((
                BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiberContacts(
                    contacts,
                ),
                None,
            )) = circle
                .rational_intersections_with_parameter_map(&cutter, &policy)
                .unwrap()
            else {
                panic!("the general rational contact must remain in the selected fiber");
            };
            let [contact] = contacts.as_slice() else {
                panic!("the selected half circle must retain exactly its left contact");
            };
            assert_eq!(
                std::mem::size_of::<BezierAlgebraicCuspSemicircleSelectedFiberContact2>(),
                std::mem::size_of::<usize>(),
            );
            assert_eq!(
                contact.location(),
                BezierAlgebraicCuspSemicircleContactLocation2::Interior,
            );
            assert_eq!(contact.tangent_cross_sign(), RealSign::Positive);
            assert_eq!(
                contact
                    .other_parameter()
                    .order_to_real(&quarter, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
            assert_eq!(
                contact
                    .other_parameter()
                    .order_to_real(&half, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
            let cusp_parameter = contact.cusp_parameter();
            assert_eq!(
                cusp_parameter.order_to_real(&half, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                contact
                    .point_coordinate_order_to_real(Axis2::X, &Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );
            assert_eq!(
                contact
                    .point_coordinate_order_to_real(Axis2::Y, &Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            let Classification::Decided(bounds) =
                algebraic_chord_endpoint_bounds_refined(&contact.point_evidence(), 8, &policy)
            else {
                panic!("the selected-fiber rational point must refine exactly");
            };
            assert_eq!(
                bounds.contains_point(&Point2::from_values(0, 0), &policy),
                Classification::Decided(false),
            );

            // This independent analytic parallel does not share the
            // intersection map that authored the selected endpoint. The
            // retained-chord authority must still decide their exact tangent
            // relation without adjoining either selected field.
            let fragment = BezierAlgebraicCuspSemicircleFragment2::from_certified_range(
                circle.clone(),
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                cusp_parameter,
                false,
                &policy,
            );
            assert!(matches!(
                fragment
                    .endpoint_tangent_cross_dot_linear_combination_retained_parallel(
                        false,
                        &independent_parallel,
                        &BezierParameter2::Exact(half.clone()),
                        RealSign::Positive,
                        &Real::one(),
                        &Real::zero(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(Some(RealSign::Positive | RealSign::Negative)),
            ));
        }
    }

    #[test]
    fn selected_parallel_normal_circle_retains_general_rational_overlaps_in_one_fiber() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let one_third = (Real::one() / Real::from(3_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        // x(t)=t+t^2 and alpha^2+alpha=1/2 make the selected
        // algebraic frame's Cartesian center exactly (1/2, 0). The retained
        // alpha remains genuinely algebraic, so the coincident rational
        // quarter circle must be proven in the selected fiber rather than by
        // the rational-frame circle fast path.
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let quarter_circle = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::new(half.clone(), Real::one()),
                Point2::new(-half.clone(), Real::one()),
                Point2::new(-half.clone(), Real::zero()),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        );
        // v=4u(1-u) folds the same quarter-circle image at u=1/2.
        // The component replay must retain both monotone cells and their
        // opposite orientations.
        let eleven = Real::from(11_i8);
        let folded_quarter = RationalBezier2::try_new(
            vec![
                Point2::new(half.clone(), Real::one()),
                Point2::new(half.clone() - Real::from(2_i8), Real::one()),
                Point2::new(
                    &half - (Real::from(8_i8) / &eleven).unwrap(),
                    (Real::from(-5_i8) / &eleven).unwrap(),
                ),
                Point2::new(half.clone() - Real::from(2_i8), Real::one()),
                Point2::new(half.clone(), Real::one()),
            ],
            vec![
                Real::one(),
                Real::one(),
                (&eleven / Real::from(3_i8)).unwrap(),
                Real::one(),
                Real::one(),
            ],
        )
        .unwrap();
        let opposite_quarter = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::new(half.clone(), Real::one()),
                Point2::new(&half + Real::one(), Real::one()),
                Point2::new(&half + Real::one(), Real::zero()),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        );

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the algebraic selected circle must construct");
            };
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiberOverlaps(
                    overlaps,
                ),
            ) = circle
                .rational_intersections(&quarter_circle, &policy)
                .unwrap()
            else {
                panic!("the rational circle component must remain in the selected fiber");
            };
            let [overlap] = overlaps.as_slice() else {
                panic!("the selected rational quarter must retain one monotone overlap");
            };
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Same,
            );
            assert_eq!(
                overlap
                    .other_start_parameter()
                    .order_to_real(&Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                overlap
                    .other_end_parameter()
                    .order_to_real(&Real::one(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                overlap
                    .cusp_start_parameter()
                    .order_to_real(&Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                overlap
                    .cusp_end_parameter()
                    .order_to_real(&half, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let Classification::Decided(other_cut) = overlap
                .other_parameter_for_cusp(
                    &BezierAlgebraicCuspSemicircleParameter2::Exact(quarter.clone()),
                    &policy,
                )
                .unwrap()
            else {
                panic!("an exact cusp cut must invert into the selected rational fiber");
            };
            assert_eq!(
                other_cut.order_to_real(&one_third, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            let Classification::Decided(round_trip) = overlap
                .cusp_parameter_for_other(&other_cut, &policy)
                .unwrap()
            else {
                panic!("the selected rational cut must map back to the cusp domain");
            };
            assert_eq!(
                round_trip.order_to_real(&quarter, &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            let Classification::Decided(point) = overlap
                .point_evidence_for_other(&other_cut, &policy)
                .unwrap()
            else {
                panic!("the selected rational cut must retain exact point evidence");
            };
            assert_eq!(
                point.same_point(
                    &RationalBezierIntersectionPointEvidence2::Exact(Point2::new(
                        -(Real::one() / Real::from(10_i8)).unwrap(),
                        (Real::from(4_i8) / Real::from(5_i8)).unwrap(),
                    )),
                    &policy,
                ),
                Classification::Decided(true),
            );

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiberOverlaps(
                    reversed_overlaps,
                ),
            ) = circle
                .rational_intersections(&quarter_circle.reversed(), &policy)
                .unwrap()
            else {
                panic!("rational reversal must retain the selected-fiber component");
            };
            let [reversed] = reversed_overlaps.as_slice() else {
                panic!("the reversed quarter must retain one overlap");
            };
            assert_eq!(
                reversed.orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
            let Classification::Decided(reversed_cut) = reversed
                .other_parameter_for_cusp(
                    &BezierAlgebraicCuspSemicircleParameter2::Exact(quarter.clone()),
                    &policy,
                )
                .unwrap()
            else {
                panic!("the reversed selected overlap must invert exactly");
            };
            assert_eq!(
                reversed_cut
                    .order_to_real(&(Real::one() - &one_third), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiberOverlaps(folded),
            ) = circle
                .rational_intersections(&folded_quarter, &policy)
                .unwrap()
            else {
                panic!("a stationary selected-fiber circle must split into monotone overlaps");
            };
            assert_eq!(folded.len(), 2);
            assert_eq!(
                folded[0].orientation(),
                RationalBezierOverlapOrientation2::Same,
            );
            assert_eq!(
                folded[1].orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
            for (overlap, expected_start, expected_end) in [
                (&folded[0], Real::zero(), half.clone()),
                (&folded[1], half.clone(), Real::one()),
            ] {
                assert_eq!(
                    overlap
                        .other_start_parameter()
                        .order_to_real(&expected_start, &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
                assert_eq!(
                    overlap
                        .other_end_parameter()
                        .order_to_real(&expected_end, &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleRationalIntersections2::SelectedFiberContacts(
                    opposite_contacts,
                ),
            ) = circle
                .rational_intersections(&opposite_quarter, &policy)
                .unwrap()
            else {
                panic!("an opposite selected-fiber quarter must retain its shared endpoint");
            };
            let [opposite_contact] = opposite_contacts.as_slice() else {
                panic!("the opposite quarter must touch exactly one selected endpoint");
            };
            assert_eq!(
                opposite_contact.location(),
                BezierAlgebraicCuspSemicircleContactLocation2::Start,
            );
            assert_eq!(opposite_contact.tangent_cross_sign(), RealSign::Zero);
        }
    }

    #[test]
    fn genuine_parallel_algebraic_ray_replays_the_unsquared_branch() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let source = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(1, 1),
        );
        let parallel = source.parallel_left(quarter).unwrap();
        let query_curve = RationalBezier2::try_new(
            vec![Point2::from_values(0, 0), Point2::from_values(0, 1)],
            vec![Real::one(), Real::one()],
        )
        .unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                parallel.exact_rational_parallel_component(&policy).unwrap(),
                Classification::Decided(None)
            ));
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::zero(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the algebraic query polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(half.clone(), Real::one(), &policy).unwrap()
            else {
                panic!("the algebraic query interval must construct");
            };
            let Classification::Decided(parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the algebraic query parameter must isolate");
            };
            let query = query_curve
                .point_at_algebraic_parameter(&parameter, &policy)
                .unwrap();
            let Classification::Decided(query) = query.predicate_evaluator(&policy).unwrap() else {
                panic!("the algebraic query predicate must construct");
            };
            let range = CurveRegionParameterRange2::from_bezier_range(
                BezierParameterRange2::new_validated(
                    BezierParameter2::Exact(Real::zero()),
                    BezierParameter2::Exact(Real::one()),
                ),
            );
            let endpoint = |parameter: Real| {
                let Classification::Decided(point) =
                    parallel.point_at(&parameter, &policy).unwrap()
                else {
                    panic!("the represented parallel endpoint must evaluate");
                };
                RationalBezierIntersectionPointEvidence2::Exact(point)
            };
            let endpoints = [endpoint(Real::zero()), endpoint(Real::one())];
            let Classification::Decided(forward) = BezierParallelAlgebraicRay2::try_new(
                parallel.clone(),
                range.clone(),
                false,
                endpoints.clone(),
                &policy,
            )
            .unwrap() else {
                panic!("the genuine parallel ray evaluator must construct");
            };
            assert_eq!(
                forward
                    .endpoint_side_signs(&query, &Real::zero(), &Real::one(), &policy,)
                    .unwrap(),
                Classification::Decided([RealSign::Negative, RealSign::Positive]),
            );
            assert_eq!(
                forward.contains_point(&query, &policy).unwrap(),
                Classification::Decided(false),
            );
            assert_eq!(
                forward
                    .forward_ray_winding_delta(&query, &Real::one(), &Real::zero(), &policy,)
                    .unwrap(),
                Classification::Decided(1),
            );

            let Classification::Decided(reversed) = BezierParallelAlgebraicRay2::try_new(
                parallel.clone(),
                range.clone(),
                true,
                endpoints.clone(),
                &policy,
            )
            .unwrap() else {
                panic!("the reversed genuine parallel ray evaluator must construct");
            };
            assert_eq!(
                reversed
                    .forward_ray_winding_delta(&query, &Real::one(), &Real::zero(), &policy,)
                    .unwrap(),
                Classification::Decided(-1),
            );
        }
    }

    #[test]
    fn selected_parallel_normal_circle_reuses_rationalized_analytic_parallel_components() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let analytic_quarter = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::new(half.clone(), Real::from(2_i8)),
                Point2::new(half.clone() - Real::from(2_i8), Real::from(2_i8)),
                Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        )
        .parallel_left(Real::one())
        .unwrap();
        let opposite_analytic_quarter = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::new(half.clone(), Real::from(2_i8)),
                Point2::new(&half + Real::from(2_i8), Real::from(2_i8)),
                Point2::new(&half + Real::from(2_i8), Real::zero()),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        )
        .parallel_left(Real::from(-1_i8))
        .unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the algebraic selected circle must construct");
            };
            assert!(matches!(
                analytic_quarter
                    .exact_rational_parallel_component(&policy)
                    .unwrap(),
                Classification::Decided(Some(_))
            ));

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiberOverlaps(
                    overlaps,
                ),
            ) = circle
                .parallel_intersections(&analytic_quarter, &policy)
                .unwrap()
            else {
                panic!("the exact analytic offset must reuse the selected rational fiber");
            };
            let [overlap] = overlaps.as_slice() else {
                panic!("the analytic quarter must retain one monotone overlap");
            };
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Same,
            );
            assert_eq!(
                overlap
                    .other_start_parameter()
                    .order_to_real(&Real::zero(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                overlap
                    .other_end_parameter()
                    .order_to_real(&Real::one(), &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiberOverlaps(
                    reversed,
                ),
            ) = circle
                .parallel_intersections(&analytic_quarter.reversed(), &policy)
                .unwrap()
            else {
                panic!("analytic reversal must retain the selected rational fiber");
            };
            let [reversed] = reversed.as_slice() else {
                panic!("the reversed analytic quarter must retain one overlap");
            };
            assert_eq!(
                reversed.orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );

            let cusp_overlap_start = overlap.cusp_start_parameter();
            let cusp_overlap_end = overlap.cusp_end_parameter();
            let Classification::Decided(first_cut) = cusp_overlap_start
                .strict_rational_between(&cusp_overlap_end, &policy)
                .unwrap()
            else {
                panic!("the cusp overlap must expose a represented interior cut");
            };
            let first_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(first_cut);
            let Classification::Decided(second_cut) = first_cut
                .strict_rational_between(&cusp_overlap_end, &policy)
                .unwrap()
            else {
                panic!("the cusp overlap must expose a second represented interior cut");
            };
            let second_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(second_cut);
            let Classification::Decided(selected_start) = overlap
                .other_parameter_for_cusp(&first_cut, &policy)
                .unwrap()
            else {
                panic!("the first selected analytic cut must map exactly");
            };
            let Classification::Decided(selected_end) = overlap
                .other_parameter_for_cusp(&second_cut, &policy)
                .unwrap()
            else {
                panic!("the second selected analytic cut must map exactly");
            };
            assert!(selected_start.represented_value().is_none());
            assert!(selected_end.represented_value().is_none());
            let selected_carrier_range = crate::CurveRegionParameterRange2::new_validated(
                crate::CurveRegionParameter2::from_selected_fiber(selected_start.clone()),
                crate::CurveRegionParameter2::from_selected_fiber(selected_end.clone()),
            );
            let cusp_range = |start, end| {
                CurveRegionParameterRange2::new_validated(
                    CurveRegionParameter2::from_algebraic_cusp(start),
                    CurveRegionParameter2::from_algebraic_cusp(end),
                )
            };
            assert_eq!(
                overlap
                    .has_positive_curve_region_overlap(
                        &cusp_range(
                            BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                            first_cut.clone(),
                        ),
                        &selected_carrier_range,
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(false),
                "independently nonempty trims that correspond only at one endpoint must not become a fillet overlap",
            );
            assert_eq!(
                overlap
                    .has_positive_curve_region_overlap(
                        &cusp_range(first_cut.clone(), second_cut.clone()),
                        &selected_carrier_range,
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(true),
            );
            let unit = BezierParameterRange2::new_validated(
                BezierParameter2::Exact(Real::zero()),
                BezierParameter2::Exact(Real::one()),
            );
            let ordinary_carrier_range =
                crate::CurveRegionParameterRange2::from_bezier_range(unit.clone());
            let (same_first, same_second) =
                crate::curve_region_boolean::clip_aligned_parameter_overlap_for_test(
                    &unit,
                    &unit,
                    false,
                    &selected_carrier_range,
                    &ordinary_carrier_range,
                    &policy,
                )
                .expect("same-oriented selected analytic overlap clipping must complete")
                .expect("the selected analytic carrier lies inside the complete overlap");
            assert_eq!(same_first, selected_carrier_range);
            assert_eq!(same_second, selected_carrier_range);

            let reversed_unit = BezierParameterRange2::new_validated(
                BezierParameter2::Exact(Real::one()),
                BezierParameter2::Exact(Real::zero()),
            );
            let (reversed_first, reversed_second) =
                crate::curve_region_boolean::clip_aligned_parameter_overlap_for_test(
                    &unit,
                    &reversed_unit,
                    true,
                    &selected_carrier_range,
                    &ordinary_carrier_range,
                    &policy,
                )
                .expect("reversed selected analytic overlap clipping must complete")
                .expect("the selected analytic carrier lies inside the reversed overlap");
            assert_eq!(reversed_first, selected_carrier_range);
            assert_eq!(
                reversed_second,
                crate::CurveRegionParameterRange2::new_validated(
                    crate::CurveRegionParameter2::from_selected_fiber(
                        selected_start.unit_complement(),
                    ),
                    crate::CurveRegionParameter2::from_selected_fiber(
                        selected_end.unit_complement(),
                    ),
                )
            );
            assert_eq!(
                reversed_second
                    .start()
                    .as_selected_fiber()
                    .unwrap()
                    .unit_complement()
                    .cmp_by_refinement(
                        selected_carrier_range.start().as_selected_fiber().unwrap(),
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );

            let cusp_fragment =
                |start: BezierAlgebraicCuspSemicircleParameter2,
                 end: BezierAlgebraicCuspSemicircleParameter2| {
                    match start.cmp_by_refinement(&end, &policy).unwrap() {
                        Classification::Decided(std::cmp::Ordering::Less) => {
                            let Classification::Decided(fragment) =
                                BezierAlgebraicCuspSemicircleFragment2::try_new(
                                    circle.clone(),
                                    start,
                                    end,
                                    false,
                                    &policy,
                                )
                                .unwrap()
                            else {
                                panic!("the retained cusp complement must construct");
                            };
                            Some(BezierSplitFragment2::AlgebraicCuspSemicircle(fragment))
                        }
                        Classification::Decided(std::cmp::Ordering::Equal) => None,
                        Classification::Decided(std::cmp::Ordering::Greater)
                        | Classification::Uncertain(_) => {
                            panic!("the retained cusp complement must be ordered")
                        }
                    }
                };
            let selected_before = cusp_fragment(
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                first_cut.clone(),
            )
            .expect("the first selected cut is strictly interior");
            let selected_after = cusp_fragment(
                second_cut.clone(),
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::one()),
            )
            .expect("the second selected cut is strictly interior");
            let selected_endpoint = |fragment: &BezierSplitFragment2, start_endpoint| {
                let BezierSplitFragment2::AlgebraicCuspSemicircle(fragment) = fragment else {
                    unreachable!("the selected complement retained its cusp carrier")
                };
                let Classification::Decided(Some(point)) = fragment
                    .endpoint_point_evidence(start_endpoint, &policy)
                    .unwrap()
                else {
                    panic!("the selected complement must retain endpoint point evidence");
                };
                point
            };
            let selected_start_point = selected_endpoint(&selected_before, false);
            let selected_end_point = selected_endpoint(&selected_after, true);
            let selected_fragments = vec![
                selected_before,
                BezierSplitFragment2::SelectedFiber(
                    crate::bezier_split::BezierSelectedFiberFragment2::new(
                        crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(
                            analytic_quarter.clone(),
                        ),
                        selected_carrier_range.clone(),
                        selected_start_point,
                        selected_end_point,
                    ),
                ),
                selected_after,
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(
                        circle.complementary_half(),
                        &policy,
                    ),
                ),
            ];
            let selected_boundary = CurveRegionBoundaryLoop2::new(selected_fragments, &policy)
                .expect("the selected analytic boundary must close exactly");
            let selected_region = CurveRegion2::try_new_with_loop_topology(
                vec![selected_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            let reference_boundary = CurveRegionBoundaryLoop2::new(
                vec![
                    BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(circle.clone(), &policy),
                    ),
                    BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(
                            circle.complementary_half(),
                            &policy,
                        ),
                    ),
                ],
                &policy,
            )
            .unwrap();
            let reference_region = CurveRegion2::try_new_with_loop_topology(
                vec![reference_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            for style in [
                OffsetCornerStyle2::Round,
                OffsetCornerStyle2::Bevel,
                OffsetCornerStyle2::Miter {
                    limit: Real::from(4_i8),
                },
            ] {
                let distance = (Real::one() / Real::from(10_i8)).unwrap();
                let selected_offset = selected_region
                    .offset(distance.clone(), &style, &policy)
                    .unwrap_or_else(|error| {
                        panic!(
                            "a selected analytic overlap must offset through its true carrier switches: policy={policy:?}, style={style:?}, error={error:?}"
                        )
                    });
                let reference_offset = reference_region
                    .offset(distance, &style, &policy)
                    .expect("the equivalent retained circle must offset");
                assert_eq!(selected_offset.certainty, CurveCertainty::Certified);
                assert_eq!(selected_offset.certainty, reference_offset.certainty);
                for point in [
                    Point2::new(half.clone(), Real::zero()),
                    Point2::new(&half + Real::from(2_i8), Real::zero()),
                    Point2::new(&half - Real::from(2_i8), Real::zero()),
                ] {
                    assert_eq!(
                        selected_offset
                            .value
                            .classify_point(&point, &policy)
                            .unwrap()
                            .value,
                        reference_offset
                            .value
                            .classify_point(&point, &policy)
                            .unwrap()
                            .value,
                    );
                }
                assert!(
                    selected_offset
                        .value
                        .boundary_loops()
                        .iter()
                        .flat_map(CurveRegionBoundaryLoop2::fragments)
                        .all(|fragment| !matches!(
                            fragment,
                            BezierSplitFragment2::SelectedFiber(_)
                        ))
                );
            }

            let Classification::Decided(wide_start_cut) = cusp_overlap_start
                .strict_rational_between(&first_cut, &policy)
                .unwrap()
            else {
                panic!("the analytic overlap must expose a wider first cut");
            };
            let wide_start_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(wide_start_cut);
            let Classification::Decided(wide_end_cut) = second_cut
                .strict_rational_between(&cusp_overlap_end, &policy)
                .unwrap()
            else {
                panic!("the analytic overlap must expose a wider second cut");
            };
            let wide_end_cut = BezierAlgebraicCuspSemicircleParameter2::Exact(wide_end_cut);
            let Classification::Decided(wide_selected_start) = overlap
                .other_parameter_for_cusp(&wide_start_cut, &policy)
                .unwrap()
            else {
                panic!("the wider first analytic cut must map exactly");
            };
            let Classification::Decided(wide_selected_end) = overlap
                .other_parameter_for_cusp(&wide_end_cut, &policy)
                .unwrap()
            else {
                panic!("the wider second analytic cut must map exactly");
            };
            let analytic_before = cusp_fragment(
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                wide_start_cut,
            )
            .expect("the wider first selected cut is strictly interior");
            let analytic_after = cusp_fragment(
                wide_end_cut,
                BezierAlgebraicCuspSemicircleParameter2::Exact(Real::one()),
            )
            .expect("the wider second selected cut is strictly interior");
            let analytic_start_point = selected_endpoint(&analytic_before, false);
            let analytic_end_point = selected_endpoint(&analytic_after, true);
            let analytic_fragments = vec![
                analytic_before,
                BezierSplitFragment2::SelectedFiber(
                    crate::bezier_split::BezierSelectedFiberFragment2::new(
                        crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(
                            analytic_quarter.clone(),
                        ),
                        crate::CurveRegionParameterRange2::new_validated(
                            crate::CurveRegionParameter2::from_selected_fiber(wide_selected_start),
                            crate::CurveRegionParameter2::from_selected_fiber(wide_selected_end),
                        ),
                        analytic_start_point,
                        analytic_end_point,
                    ),
                ),
                analytic_after,
                BezierSplitFragment2::AlgebraicCuspSemicircle(
                    BezierAlgebraicCuspSemicircleFragment2::full(
                        circle.complementary_half(),
                        &policy,
                    ),
                ),
            ];
            let analytic_boundary = CurveRegionBoundaryLoop2::new(analytic_fragments, &policy)
                .expect("the complete analytic overlap boundary must close exactly");
            let analytic_region = CurveRegion2::try_new_with_loop_topology(
                vec![analytic_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            let evidence = selected_region
                .intersect_region(&analytic_region, &policy)
                .expect("a selected analytic carrier must re-enter overlap clipping")
                .into_value();
            assert!(evidence.blockers().is_empty());
            assert!(evidence.overlaps().iter().any(|overlap| {
                overlap.first_range().start().is_selected_fiber()
                    || overlap.second_range().start().is_selected_fiber()
            }));
            let booleans = selected_region
                .boolean_regions(&analytic_region, &policy)
                .expect("a selected analytic carrier must re-enter Boolean topology")
                .into_value();
            assert!(!booleans.union().is_empty());
            assert!(!booleans.intersection().is_empty());
            assert!(booleans.difference().is_empty());
            assert!(booleans.xor().is_empty());

            let Classification::Decided(
                BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiberContacts(
                    contacts,
                ),
            ) = circle
                .parallel_intersections(&opposite_analytic_quarter, &policy)
                .unwrap()
            else {
                panic!("the opposite analytic quarter must retain its selected endpoint");
            };
            let [contact] = contacts.as_slice() else {
                panic!("the opposite analytic quarter must touch exactly one endpoint");
            };
            assert_eq!(
                contact.location(),
                BezierAlgebraicCuspSemicircleContactLocation2::Start,
            );
            assert_eq!(contact.tangent_cross_sign(), RealSign::Zero);
        }
    }

    #[test]
    fn selected_parallel_normal_incident_circle_selects_the_positive_speed_component() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        // x(u)=u+u^2 and alpha^2+alpha=1/2 retain a genuinely
        // algebraic selected center at (1/2, 0).
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let carrier = RationalBezier2::from(
            RationalQuadraticBezier2::try_new(
                Point2::new(half.clone(), Real::from(2_i8)),
                Point2::new(half.clone() - Real::from(2_i8), Real::from(2_i8)),
                Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap(),
        )
        .parallel_left(Real::one())
        .unwrap();
        let range = BezierParameterRange2::new_validated(
            BezierParameter2::Exact(Real::zero()),
            BezierParameter2::Exact(Real::one()),
        );

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                carrier.exact_rational_parallel_component(&policy).unwrap(),
                Classification::Decided(Some(_)),
            ));
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the exact selected-normal circle must construct");
            };
            for analytic in [carrier.clone(), carrier.reversed()] {
                assert!(matches!(
                    circle
                        .parallel_intersections_with_incident_ray(
                            &analytic,
                            &range,
                            &incident_domain(
                                &analytic,
                                Real::one(),
                                BezierParameterRayDirection2::Increasing,
                                &policy,
                            ),
                            &policy,
                        )
                        .unwrap(),
                    Classification::Decided(
                        BezierAlgebraicCuspSemicircleParallelIntersections2::CoincidentCircleComponent
                    ),
                ));
            }
        }
    }

    #[test]
    fn selected_affine_tangent_source_retains_incident_endpoint_and_contacts_locally() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let center_parameter = BezierParameter2::Exact(quarter.clone());
        // P(u)=(u,0), and Q(t)=P(2t), force the retained contact u=5/4
        // beyond the canonical source unit interval while its edited-carrier
        // parameter t=5/8 remains finite.
        let center_support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(1, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let tangent_support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(1, 0),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let range = BezierParameterRange2::from_exact(Real::zero(), Real::one());
        let expected = (Real::from(5_i8) / Real::from(8_i8)).unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(tangent_parameter) = center_parameter
                .affine_image_unbounded(&half, &Real::zero(), &policy)
                .unwrap()
            else {
                panic!("the positive affine center chart must decide exactly");
            };
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    center_support.clone(),
                    center_parameter.clone(),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-normal circle must construct");
            };
            let circle = circle
                .with_certified_parallel_normal_tangent_authority(
                    tangent_support.clone(),
                    tangent_parameter.clone(),
                    Real::from(2_i8),
                    Real::zero(),
                    &policy,
                )
                .unwrap();
            let endpoint =
                degree_nine_selected_fiber_parameter_for_test(half.clone(), 32_768, &policy);
            assert!(matches!(
                endpoint.promoted_bezier_parameter(&policy).unwrap(),
                Classification::Uncertain(_)
            ));
            let endpoint = CurveRegionParameter2::from_selected_fiber(endpoint);
            let Classification::Decided(mapped_endpoint) = affine_tangent_source_region_parameter(
                &endpoint,
                &tangent_parameter,
                &center_parameter,
                &Real::from(2_i8),
                &Real::zero(),
                &policy,
            )
            .unwrap() else {
                panic!("a selected incident endpoint must cross the affine chart locally");
            };
            assert!(matches!(
                mapped_endpoint
                    .as_selected_fiber()
                    .expect("the mapped incident endpoint must remain selected")
                    .promoted_bezier_parameter(&policy)
                    .unwrap(),
                Classification::Uncertain(_)
            ));

            for range in [range.clone(), range.reversed()] {
                let mut retained = Vec::new();
                for half_circle in [circle.clone(), circle.complementary_half()] {
                    let result = half_circle
                        .parallel_intersections_in_range(&tangent_support, &range, &policy)
                        .unwrap();
                    let Classification::Decided(
                        BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiberContacts(
                            contacts,
                        ),
                    ) = result
                    else {
                        panic!(
                            "an affine carrier switch must retain its selected incident contacts: {result:?}"
                        );
                    };
                    retained.extend(contacts);
                }
                assert_eq!(retained.len(), 1);
                let parameter = retained[0].other_parameter();
                assert_eq!(parameter.represented_value(), Some(&expected));
                assert_eq!(
                    parameter
                        .cmp_bezier_parameter(&BezierParameter2::Exact(expected.clone()), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }
        }
    }

    #[test]
    fn selected_fiber_interval_supports_exact_and_nonexact_exterior_roots() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let three_halves = &Real::from(3_i8) * &half;
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            // Retain alpha=1/2 as algebraic construction evidence. Refinement
            // recovers its exact value, which exercises the exterior
            // exact-retained path without changing the selected authority.
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the rational retained-root polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), Real::one(), &policy).unwrap()
            else {
                panic!("the retained-root interval must construct");
            };
            let Classification::Decided(retained) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the retained rational root must isolate");
            };

            // u^2=1+alpha selects sqrt(3/2) strictly between 1 and 2.
            let nonlinear_incidence = BivariatePolynomial::new(vec![
                vec![Real::from(-1_i8), Real::zero(), Real::one()],
                vec![Real::from(-1_i8)],
            ]);
            let outside_unit_predicate =
                BivariatePolynomial::new(vec![vec![Real::from(-1_i8), Real::zero(), Real::one()]]);
            let exterior_range = BezierParameterRange2::from_exact(Real::one(), Real::from(2_i8));
            for exterior_range in [exterior_range.clone(), exterior_range.reversed()] {
                let Classification::Decided(Some(nonlinear)) =
                    selected_fiber_parameters_in_bezier_range(
                        &nonlinear_incidence,
                        &retained,
                        &exterior_range,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the nonlinear exterior fiber must isolate");
                };
                let [nonlinear] = nonlinear.as_slice() else {
                    panic!("the positive exterior interval must contain one nonlinear root");
                };
                assert!(nonlinear.represented_value().is_none());
                assert_eq!(
                    nonlinear.order_to_real(&Real::one(), &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    nonlinear.order_to_real(&Real::from(2_i8), &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
                assert_eq!(
                    nonlinear
                        .predicate_sign(&outside_unit_predicate, &policy)
                        .unwrap(),
                    Classification::Decided(RealSign::Positive),
                );
            }

            // u=1+alpha recovers the represented exterior root 3/2. This is
            // valid affine evidence even though it is not a bounded Bezier
            // parameter until the caller maps it back into its target chart.
            let linear_incidence = BivariatePolynomial::new(vec![
                vec![Real::from(-1_i8), Real::one()],
                vec![Real::from(-1_i8)],
            ]);
            let Classification::Decided(Some(linear)) = selected_fiber_parameters_in_bezier_range(
                &linear_incidence,
                &retained,
                &exterior_range,
                &policy,
            )
            .unwrap() else {
                panic!("the linear exterior fiber must isolate");
            };
            let [linear] = linear.as_slice() else {
                panic!("the exterior interval must contain one represented root");
            };
            assert_eq!(linear.represented_value(), Some(&three_halves));
            assert_eq!(
                linear.predicate_sign(&linear_incidence, &policy).unwrap(),
                Classification::Decided(RealSign::Zero),
            );
        }
    }

    #[test]
    fn selected_parallel_normal_positive_dimensional_projection_rejects_conjugate_components() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let BezierParameter2::Algebraic(center) =
            algebraic_parameter(vec![-half.clone(), Real::zero(), Real::one()])
        else {
            panic!("sqrt(1/2) must retain its algebraic authority");
        };
        let zero = BivariatePolynomial::new(vec![vec![Real::zero()]]);
        let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let target_speed =
            BivariatePolynomial::new(vec![vec![Real::one(), Real::zero(), Real::one()]]);
        let center_speed = one.clone();
        let circle = BezierParallelTwoNormalExpression2 {
            product: zero.clone(),
            center: one.clone(),
            candidate: zero.clone(),
            rational: one.clone(),
        };
        // The authored expression is 1+sqrt(1)=2, hence never zero. Its
        // once-squared branch is 2+2sqrt(1)=4, but the final norm vanishes
        // identically because its opposite center-speed conjugate is zero.
        let squared_branch = BezierAlgebraicCuspTwoTermExpression2 {
            rational: BivariatePolynomial::new(vec![vec![Real::from(2_i8)]]),
            radical: BivariatePolynomial::new(vec![vec![Real::from(2_i8)]]),
        };
        let exterior_branch = BezierAlgebraicCuspTwoTermExpression2 {
            // u^2=1+alpha has one positive root strictly between 1 and 2.
            rational: BivariatePolynomial::new(vec![
                vec![Real::from(-1_i8), Real::zero(), Real::one()],
                vec![Real::from(-1_i8)],
            ]),
            radical: zero.clone(),
        };
        let exterior_range = BezierParameterRange2::from_exact(Real::one(), Real::from(2_i8));
        let unit_range = BezierParameterRange2::from_exact(Real::zero(), Real::one());
        let square_speed =
            BivariatePolynomial::new(vec![vec![Real::one(), Real::from(-2_i8), Real::one()]]);
        let square_circle = BezierParallelTwoNormalExpression2 {
            product: zero.clone(),
            center: zero.clone(),
            candidate: one.clone(),
            rational: BivariatePolynomial::new(vec![vec![
                -(Real::from(3_i8) / Real::from(2_i8)).unwrap(),
            ]]),
        };
        let square_range = BezierParameterRange2::from_exact(Real::from(2_i8), Real::from(3_i8));
        let square_contact = (Real::from(5_i8) / Real::from(2_i8)).unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                selected_parallel_normal_positive_dimensional_projection(
                    &circle,
                    &squared_branch,
                    &center_speed,
                    &target_speed,
                    &center,
                    None,
                    None,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(
                    BezierSelectedParallelNormalPositiveProjection2::Candidates(ref candidates)
                ) if candidates.is_empty(),
            ));
            for exterior_range in [exterior_range.clone(), exterior_range.reversed()] {
                let Classification::Decided(
                    BezierSelectedParallelNormalPositiveProjection2::Candidates(candidates),
                ) = selected_parallel_normal_positive_dimensional_projection(
                    &circle,
                    &exterior_branch,
                    &center_speed,
                    &target_speed,
                    &center,
                    Some(&exterior_range),
                    None,
                    &policy,
                )
                .unwrap()
                else {
                    panic!("the positive-dimensional exterior branch must project");
                };
                let [candidate] = candidates.as_slice() else {
                    panic!("the exterior branch must retain its one positive root");
                };
                assert_eq!(
                    candidate.order_to_real(&Real::one(), &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Greater),
                );
                assert_eq!(
                    candidate.order_to_real(&Real::from(2_i8), &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Less),
                );
            }

            let incident = BezierParallelIncidentDomain2 {
                endpoint: CurveRegionParameter2::from_bezier(BezierParameter2::Exact(Real::one())),
                bridge: None,
                anchor: Real::one(),
                direction: BezierParameterRayDirection2::Increasing,
                barrier: None,
            };
            let Classification::Decided(
                BezierSelectedParallelNormalPositiveProjection2::Candidates(candidates),
            ) = selected_parallel_normal_positive_dimensional_projection(
                &circle,
                &exterior_branch,
                &center_speed,
                &target_speed,
                &center,
                Some(&unit_range),
                Some(&incident),
                &policy,
            )
            .unwrap()
            else {
                panic!("the positive-dimensional incident branch must project");
            };
            assert_eq!(candidates.len(), 1);
            assert_eq!(
                candidates[0].order_to_real(&Real::one(), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Greater),
            );

            // sqrt((u-1)^2)=u-1 on [2,3], although the polynomial square
            // root selected positive at zero is 1-u. The active cell, not
            // parameter zero, must choose the authored positive-speed sheet.
            for square_range in [square_range.clone(), square_range.reversed()] {
                let Classification::Decided(
                    BezierSelectedParallelNormalPositiveProjection2::Candidates(candidates),
                ) = selected_parallel_normal_positive_dimensional_projection(
                    &square_circle,
                    &squared_branch,
                    &center_speed,
                    &square_speed,
                    &center,
                    Some(&square_range),
                    None,
                    &policy,
                )
                .unwrap()
                else {
                    panic!("the exterior square-speed sheet must project");
                };
                let [candidate] = candidates.as_slice() else {
                    panic!("the exterior square-speed sheet must retain one root");
                };
                assert_eq!(
                    candidate.order_to_real(&square_contact, &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }
        }
    }

    #[test]
    fn algebraic_center_fixed_distance_projects_complete_high_degree_fiber() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let target = RationalBezier2::try_new(
            vec![
                Point2::new(
                    (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
                    (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(-9_i8) / Real::from(20_i8)).unwrap(),
                    (Real::from(-8_i8) / Real::from(5_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(3_i8) / Real::from(10_i8)).unwrap(),
                    (Real::one() / Real::from(15_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(51_i8) / Real::from(20_i8)).unwrap(),
                    (Real::from(12_i8) / Real::from(5_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(93_i8) / Real::from(10_i8)).unwrap(),
                    (Real::from(27_i8) / Real::from(5_i8)).unwrap(),
                ),
            ],
            vec![Real::one(); 5],
        )
        .unwrap()
        .parallel_left(Real::one())
        .unwrap();
        let center = algebraic_parameter(vec![-half, Real::one(), Real::one()]);
        let setback = (Real::one() / Real::from(100_i8)).unwrap();
        let radius_squared = &setback * &setback;
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let incidence = target
                .fixed_distance_incidence_from_parameter(
                    &center,
                    &radius_squared,
                    &BezierParameterRange2::new_validated(
                        BezierParameter2::Exact(Real::zero()),
                        BezierParameter2::Exact(Real::one()),
                    ),
                    &policy,
                )
                .unwrap();
            assert!(
                matches!(incidence, Classification::Decided(ref parameters) if !parameters.is_empty()),
                "the high-degree fixed-distance fiber must project under {policy:?}: {incidence:?}"
            );
        }
    }

    #[test]
    fn algebraic_center_fixed_distance_covers_adjacent_and_incident_ray() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        // P(t)=(t^2,t) is regular everywhere. For alpha^2=1/2, the
        // fixed-distance circle centered at P(alpha) with r^2=2 contains
        // P(-alpha), strictly beyond the decreasing endpoint ray.
        let parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(Real::zero(), half.clone()),
            Point2::from_values(1, 1),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let center = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
        let range = BezierParameterRange2::new_validated(
            center.clone(),
            BezierParameter2::Exact(Real::one()),
        );

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let finite = parallel
                .fixed_distance_incidence_from_parameter(
                    &center,
                    &Real::from(2_i8),
                    &range,
                    &policy,
                )
                .unwrap();
            assert!(matches!(finite, Classification::Decided(ref roots) if roots.is_empty()));

            let extended = parallel
                .fixed_distance_incidence_from_parameter_with_incident_ray(
                    &center,
                    &Real::from(2_i8),
                    &range,
                    BezierParameterRayDirection2::Decreasing,
                    &policy,
                )
                .unwrap();
            let Classification::Decided(extended) = extended else {
                panic!("the algebraic endpoint incident ray must decide under {policy:?}");
            };
            assert!(extended.iter().any(|parameter| {
                match parameter {
                    BezierParallelFixedDistanceParameter2::Bezier(parameter) => {
                        parameter
                            .cmp_by_refinement(&BezierParameter2::Exact(Real::zero()), &policy)
                            .unwrap()
                            == Classification::Decided(std::cmp::Ordering::Less)
                    }
                    BezierParallelFixedDistanceParameter2::SelectedFiber(parameter) => {
                        parameter.order_to_real(&Real::zero(), &policy).unwrap()
                            == Classification::Decided(std::cmp::Ordering::Less)
                    }
                }
            }));
        }
    }

    #[test]
    fn algebraic_center_fixed_distance_stops_before_speed_barrier() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        // P(t)=(t^2,0) has its first decreasing speed barrier at t=0.
        // The unit-distance mate t=-sqrt(3/2) is therefore on a different
        // regular component and must not leak into endpoint extension.
        let parallel = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(0, 0),
            Point2::from_values(1, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let center = algebraic_parameter(vec![-half, Real::zero(), Real::one()]);
        let range = BezierParameterRange2::new_validated(
            center.clone(),
            BezierParameter2::Exact(Real::one()),
        );

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                parallel
                    .fixed_distance_incidence_from_parameter_with_incident_ray(
                        &center,
                        &Real::one(),
                        &range,
                        BezierParameterRayDirection2::Decreasing,
                        &policy,
                    )
                    .unwrap(),
                Classification::Decided(ref parameters) if parameters.is_empty()
            ));
        }
    }

    #[test]
    fn selected_parallel_normal_circle_intersects_genuinely_analytic_parallel_in_one_fiber() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let exact_support = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(1, 0)).unwrap(),
        )
        .parallel_left(Real::zero())
        .unwrap();
        // x(u)=u+u^2 and alpha^2+alpha=1/2 retain a genuinely
        // algebraic center parameter while placing the circle at (1/2, 0).
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        // At t=1/2 this non-PH source is (3/10,-3/5), has tangent
        // (3,4), and therefore has unit left normal (-4/5,3/5). Its unit
        // left parallel meets the selected circle at (-1/2,0) transversely.
        let target = QuadraticBezier2::new(
            Point2::new(
                (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(-1_i8) / Real::from(5_i8)).unwrap(),
                (Real::from(-3_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(23_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(7_i8) / Real::from(5_i8)).unwrap(),
            ),
        )
        .parallel_left(Real::one())
        .unwrap();
        // Composing the source parameter with s=t+t^2 moves that same
        // transverse contact to the nonrational root t^2+t=1/2 while keeping
        // the source regular on the complete unit interval.
        let reparameterized_target = RationalBezier2::try_new(
            vec![
                Point2::new(
                    (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
                    (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(-9_i8) / Real::from(20_i8)).unwrap(),
                    (Real::from(-8_i8) / Real::from(5_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(3_i8) / Real::from(10_i8)).unwrap(),
                    (Real::one() / Real::from(15_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(51_i8) / Real::from(20_i8)).unwrap(),
                    (Real::from(12_i8) / Real::from(5_i8)).unwrap(),
                ),
                Point2::new(
                    (Real::from(93_i8) / Real::from(10_i8)).unwrap(),
                    (Real::from(27_i8) / Real::from(5_i8)).unwrap(),
                ),
            ],
            vec![Real::one(); 5],
        )
        .unwrap()
        .parallel_left(Real::one())
        .unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                target.exact_rational_parallel_component(&policy).unwrap(),
                Classification::Decided(None),
            ));
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let reparameterized_contact = BezierParameter2::Algebraic(center_parameter.clone());
            let Classification::Decided(Some(circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected circle must construct");
            };
            let Classification::Decided(Some(exact_center_circle)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    exact_support.clone(),
                    BezierParameter2::Exact(half.clone()),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the exact-center selected circle must construct");
            };
            let target_range = BezierParameterRange2::new_validated(
                BezierParameter2::Exact(Real::zero()),
                BezierParameter2::Exact(half.clone()),
            );
            let reparameterized_range = BezierParameterRange2::new_validated(
                BezierParameter2::Exact(Real::zero()),
                reparameterized_contact.clone(),
            );
            let Classification::Decided(
                BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiberContacts(
                    reparameterized_contacts,
                ),
            ) = exact_center_circle
                .parallel_intersections_in_range(
                    &reparameterized_target,
                    &reparameterized_range,
                    &policy,
                )
                .unwrap()
            else {
                panic!("an exact center must retain a nonrational analytic contact");
            };
            let [reparameterized_contact_evidence] = reparameterized_contacts.as_slice() else {
                panic!("the restricted reparameterized carrier must have one contact");
            };
            assert_eq!(
                reparameterized_contact_evidence
                    .other_parameter()
                    .cmp_bezier_parameter(&reparameterized_contact, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                reparameterized_contact_evidence
                    .cusp_parameter()
                    .order_to_real(&half, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert!(
                reparameterized_contact_evidence
                    .other_parameter()
                    .represented_value()
                    .is_none()
            );
            let Classification::Decided(Some(recursive_child)) =
                BezierAlgebraicCuspSemicircle2::from_selected_circle_radial(
                    &exact_center_circle,
                    reparameterized_contact_evidence.cusp_parameter(),
                    exact_center_circle.radial_distance().clone(),
                    (Real::one() / Real::from(10_i8)).unwrap(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("an analytic selected-fiber contact must author a recursive circle");
            };
            assert!(matches!(
                recursive_child
                    .recursive_selected_radial_any_frame_authority(&policy)
                    .unwrap(),
                Classification::Decided(Some(_)),
            ));
            let Classification::Decided(circle_fragment) =
                BezierAlgebraicCuspSemicircleFragment2::try_new(
                    exact_center_circle.clone(),
                    BezierAlgebraicCuspSemicircleParameter2::Exact(Real::zero()),
                    reparameterized_contact_evidence.cusp_parameter(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the transverse selected-circle fragment must construct");
            };
            let Classification::Decided(circle_start) =
                exact_center_circle.start_point_evidence(&policy).unwrap()
            else {
                panic!("the selected-circle start must be exact");
            };
            let Classification::Decided(target_end) = reparameterized_target
                .point_at(&Real::one(), &policy)
                .unwrap()
            else {
                panic!("the reparameterized analytic endpoint must be exact");
            };
            let Classification::Decided(Some(circle_contact)) = circle_fragment
                .endpoint_point_evidence(false, &policy)
                .unwrap()
            else {
                panic!("the transverse circle cut must retain its contact point");
            };
            let selected_target = BezierSplitFragment2::SelectedFiber(
                crate::bezier_split::BezierSelectedFiberFragment2::new(
                    crate::bezier_split::BezierSelectedFiberSource2::AnalyticParallel(
                        reparameterized_target.clone(),
                    ),
                    crate::CurveRegionParameterRange2::new_validated(
                        crate::CurveRegionParameter2::from_selected_fiber(
                            reparameterized_contact_evidence.other_parameter().clone(),
                        ),
                        crate::CurveRegionParameter2::from_bezier(BezierParameter2::Exact(
                            Real::one(),
                        )),
                    ),
                    circle_contact,
                    RationalBezierIntersectionPointEvidence2::Exact(target_end.clone()),
                ),
            );
            let Classification::Decided(closing_chord) = BezierAlgebraicChord2::try_new(
                RationalBezierIntersectionPointEvidence2::Exact(target_end),
                circle_start,
                &policy,
            )
            .unwrap() else {
                panic!("the retained transverse fixture chord must construct");
            };
            let closing_line = BezierSplitFragment2::AlgebraicChord(closing_chord);
            let transverse_region = CurveRegion2::try_new_with_loop_topology(
                vec![
                    CurveRegionBoundaryLoop2::new(
                        vec![
                            BezierSplitFragment2::AlgebraicCuspSemicircle(circle_fragment),
                            selected_target,
                            closing_line,
                        ],
                        &policy,
                    )
                    .unwrap(),
                ],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            #[cfg(feature = "dispatch-trace")]
            hyperreal::dispatch_trace::reset();
            let transverse_offset_work = || {
                transverse_region.offset(
                    (Real::one() / Real::from(10_i8)).unwrap(),
                    &OffsetCornerStyle2::Round,
                    &policy,
                )
            };
            #[cfg(feature = "dispatch-trace")]
            let transverse_offset =
                hyperreal::dispatch_trace::with_recording(transverse_offset_work);
            #[cfg(not(feature = "dispatch-trace"))]
            let transverse_offset = transverse_offset_work();
            #[cfg(feature = "dispatch-trace")]
            let transverse_offset_trace = hyperreal::dispatch_trace::take_trace();
            #[cfg(feature = "dispatch-trace")]
            let transverse_offset_trace_entries = transverse_offset_trace
                .dispatch
                .iter()
                .filter(|entry| entry.layer == "hypercurve")
                .collect::<Vec<_>>();
            assert!(
                transverse_offset.is_ok(),
                "a transverse selected-fiber carrier switch must offset: policy={policy:?}, result={transverse_offset:?}{}",
                {
                    #[cfg(feature = "dispatch-trace")]
                    {
                        format!(", trace={transverse_offset_trace_entries:?}")
                    }
                    #[cfg(not(feature = "dispatch-trace"))]
                    {
                        String::new()
                    }
                }
            );
            #[cfg(feature = "dispatch-trace")]
            {
                assert!(
                    transverse_offset_trace.path_count(
                        "hypercurve",
                        "algebraic-chord-pair",
                        "recursive-tangent-parallel",
                    ) > 0,
                    "finite retained-chord clipping must use the recursive tangent/parallel authority",
                );
                assert_eq!(
                    transverse_offset_trace.path_count(
                        "hypercurve",
                        "algebraic-chord-pair",
                        "represented-endpoint-parallel",
                    ),
                    0,
                    "finite retained-chord clipping must not expand into the global represented endpoint resultant",
                );
            }
            let setback = (Real::one() / Real::from(100_i8)).unwrap();
            let fillet = transverse_region
                .fillet_loop_vertex_by_radius(
                    0,
                    1,
                    setback.clone(),
                    CurveCornerMode2::TrimOnly,
                    &policy,
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "a transverse selected-fiber carrier switch must fillet exactly: policy={policy:?}, error={error:?}"
                    )
                });
            assert_eq!(fillet.certainty, CurveCertainty::Certified);
            assert_eq!(fillet.value.candidate_count(), 3);
            assert!(matches!(fillet.value, CurveCornerSolutions2::Multiple(_)));

            let chamfer = transverse_region
                .chamfer_loop_vertex_by_setbacks(
                    0,
                    1,
                    setback.clone(),
                    setback,
                    CurveCornerMode2::TrimOnly,
                    &policy,
                )
                .unwrap_or_else(|error| {
                    panic!(
                        "a transverse selected-fiber carrier switch must chamfer exactly: policy={policy:?}, error={error:?}"
                    )
                });
            assert_eq!(chamfer.certainty, CurveCertainty::Certified);
            assert!(matches!(chamfer.value, CurveCornerSolutions2::Unique(_)));
            for circle in [circle, exact_center_circle] {
                let Classification::Decided(
                    BezierAlgebraicCuspSemicircleParallelIntersections2::SelectedFiberContacts(
                        contacts,
                    ),
                ) = circle
                    .parallel_intersections_in_range(&target, &target_range, &policy)
                    .unwrap()
                else {
                    panic!("the two-normal kernel must retain analytic contacts locally");
                };
                let contact = contacts
                    .iter()
                    .find(|contact| {
                        contact
                            .other_parameter()
                            .order_to_real(&half, &policy)
                            .unwrap()
                            == Classification::Decided(std::cmp::Ordering::Equal)
                    })
                    .expect("the authored transverse contact must be retained");
                assert_eq!(
                    contact.location(),
                    BezierAlgebraicCuspSemicircleContactLocation2::Interior,
                );
                assert_eq!(contact.tangent_cross_sign(), RealSign::Positive);
                assert_eq!(
                    contact
                        .cusp_parameter()
                        .order_to_real(&half, &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
                assert_eq!(
                    contact
                        .point_coordinate_order_to_real(Axis2::X, &(-half.clone()), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
                assert_eq!(
                    contact
                        .point_coordinate_order_to_real(Axis2::Y, &Real::zero(), &policy)
                        .unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
                let Classification::Decided(bounds) =
                    algebraic_chord_endpoint_bounds_refined(&contact.point_evidence(), 8, &policy)
                else {
                    panic!("the retained analytic point must refine without a compositum");
                };
                assert_eq!(
                    bounds.contains_point(&Point2::new(-half.clone(), Real::zero()), &policy),
                    Classification::Decided(true),
                );
            }
        }
    }

    #[test]
    fn algebraic_selected_fiber_incident_chart_preserves_affine_authority() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let BezierParameter2::Algebraic(retained_parameter) =
            algebraic_parameter(vec![-half, Real::zero(), Real::one()])
        else {
            panic!("the retained selected parameter must remain algebraic");
        };
        let incidence = BivariatePolynomial::new(vec![vec![Real::from(-2_i8), Real::one()]]);
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(parameters)) =
                selected_fiber_parameters_on_incident_ray(
                    &incidence,
                    &retained_parameter,
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    None,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected incident chart must isolate exactly");
            };
            let [parameter] = parameters.as_slice() else {
                panic!("the incident chart must retain exactly t=2");
            };
            assert_eq!(
                parameter.order_to_real(&Real::from(2_i8), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(
                parameter.promoted_bezier_parameter(&policy).unwrap(),
                Classification::Decided(BezierParameter2::Exact(Real::from(2_i8))),
            );

            let barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
            assert!(matches!(
                selected_fiber_parameters_on_incident_ray(
                    &incidence,
                    &retained_parameter,
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    Some(&barrier),
                    &policy,
                )
                .unwrap(),
                Classification::Decided(Some(ref parameters)) if parameters.is_empty()
            ));
        }
    }

    #[test]
    #[ignore = "long exact end-to-end benchmark; about 326 seconds in an unoptimized all-feature build"]
    fn selected_fiber_genuinely_analytic_contacts_complete_region_booleans() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let target = QuadraticBezier2::new(
            Point2::new(
                (Real::from(-7_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(-13_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(-1_i8) / Real::from(5_i8)).unwrap(),
                (Real::from(-3_i8) / Real::from(5_i8)).unwrap(),
            ),
            Point2::new(
                (Real::from(23_i8) / Real::from(10_i8)).unwrap(),
                (Real::from(7_i8) / Real::from(5_i8)).unwrap(),
            ),
        )
        .parallel_left(Real::one())
        .unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            assert!(matches!(
                target.exact_rational_parallel_component(&policy).unwrap(),
                Classification::Decided(None),
            ));
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(first_half)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected circle must construct");
            };
            let selected_boundary = CurveRegionBoundaryLoop2::new(
                vec![
                    BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(first_half.clone(), &policy),
                    ),
                    BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(
                            first_half.complementary_half(),
                            &policy,
                        ),
                    ),
                ],
                &policy,
            )
            .unwrap();
            let selected_region = CurveRegion2::try_new_with_loop_topology(
                vec![selected_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            // The rational tangent charts u=10/19 and u=9/19 give exact unit
            // normals at these two nearby parameters. The narrow retained
            // range discards unrelated full-carrier projection roots before
            // their expensive selected-branch replay while keeping t=1/2
            // strictly interior.
            let target_start_parameter = (Real::from(83_i16) / Real::from(190_i16)).unwrap();
            let target_end_parameter = (Real::from(389_i16) / Real::from(684_i16)).unwrap();
            let Classification::Decided(target_fragment) = BezierParallelFragment2::try_new(
                target.clone(),
                BezierParameterRange2::new_validated(
                    BezierParameter2::Exact(target_start_parameter.clone()),
                    BezierParameter2::Exact(target_end_parameter.clone()),
                ),
                &policy,
            )
            .unwrap() else {
                panic!("the genuinely analytic target must remain regular");
            };
            let Classification::Decided(target_start) =
                target.point_at(&target_start_parameter, &policy).unwrap()
            else {
                panic!("the target start must be represented");
            };
            let Classification::Decided(target_end) =
                target.point_at(&target_end_parameter, &policy).unwrap()
            else {
                panic!("the target end must be represented");
            };
            let line_fragment = |start, end| BezierSplitFragment2::Materialized {
                start: BezierParameter2::Exact(Real::zero()),
                end: BezierParameter2::Exact(Real::one()),
                curve: BezierSubcurve2::Quadratic(QuadraticBezier2::from_line_segment(
                    LineSeg2::try_new(start, end).unwrap(),
                )),
            };
            let upper_right = Point2::from_values(4, 3);
            let lower_right = Point2::from_values(4, -3);
            let target_boundary = CurveRegionBoundaryLoop2::new(
                vec![
                    BezierSplitFragment2::AnalyticParallel(target_fragment),
                    line_fragment(target_end, upper_right.clone()),
                    line_fragment(upper_right, lower_right.clone()),
                    line_fragment(lower_right, target_start),
                ],
                &policy,
            )
            .unwrap();
            let target_region = CurveRegion2::try_new_with_loop_topology(
                vec![target_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Right],
            )
            .unwrap();

            let evidence = selected_region
                .intersect_region(&target_region, &policy)
                .expect("a selected circle must intersect a genuinely analytic region")
                .into_value();
            assert!(evidence.blockers().is_empty());
            assert!(evidence.contacts().iter().any(|contact| {
                contact.first_parameter().is_algebraic_cusp()
                    && contact.second_parameter().is_selected_fiber()
            }));

            let booleans = selected_region
                .boolean_regions(&target_region, &policy)
                .expect("selected-fiber analytic contacts must complete Boolean topology")
                .into_value();
            assert!(!booleans.union().is_empty());
            assert!(!booleans.intersection().is_empty());
            assert!(!booleans.difference().is_empty());
            assert!(!booleans.xor().is_empty());
            assert!(
                [
                    booleans.union(),
                    booleans.intersection(),
                    booleans.difference(),
                    booleans.xor(),
                ]
                .into_iter()
                .flat_map(|region| region.boundary_loops())
                .flat_map(CurveRegionBoundaryLoop2::fragments)
                .any(|fragment| matches!(
                    fragment,
                    BezierSplitFragment2::SelectedFiber(fragment)
                        if fragment.analytic_parallel().is_some()
                )),
                "Boolean output must retain the authored analytic selected-fiber carrier"
            );
        }
    }

    #[test]
    fn selected_fiber_rational_circle_overlaps_complete_region_booleans() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let rational_quarter = |start: Point2, control: Point2, end: Point2| {
            RationalQuadraticBezier2::try_new(
                start,
                control,
                end,
                Real::one(),
                Real::one(),
                Real::from(2_i8),
            )
            .unwrap()
        };
        let rational_circle = [
            rational_quarter(
                Point2::new(half.clone(), Real::one()),
                Point2::new(-half.clone(), Real::one()),
                Point2::new(-half.clone(), Real::zero()),
            ),
            rational_quarter(
                Point2::new(-half.clone(), Real::zero()),
                Point2::new(-half.clone(), Real::from(-1_i8)),
                Point2::new(half.clone(), Real::from(-1_i8)),
            ),
            rational_quarter(
                Point2::new(half.clone(), Real::from(-1_i8)),
                Point2::new(&half + Real::one(), Real::from(-1_i8)),
                Point2::new(&half + Real::one(), Real::zero()),
            ),
            rational_quarter(
                Point2::new(&half + Real::one(), Real::zero()),
                Point2::new(&half + Real::one(), Real::one()),
                Point2::new(half.clone(), Real::one()),
            ),
        ];

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(first_half)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the algebraic selected circle must construct");
            };
            let second_half = first_half.complementary_half();
            let quarter = (Real::one() / Real::from(4_i8)).unwrap();
            let three_quarters = &half + &quarter;
            let partial_first_half = |start: Real, end: Real| {
                let Classification::Decided(fragment) =
                    BezierAlgebraicCuspSemicircleFragment2::try_new(
                        first_half.clone(),
                        BezierAlgebraicCuspSemicircleParameter2::Exact(start),
                        BezierAlgebraicCuspSemicircleParameter2::Exact(end),
                        false,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the strict cusp partition must construct");
                };
                BezierSplitFragment2::AlgebraicCuspSemicircle(fragment)
            };
            let selected_boundary = CurveRegionBoundaryLoop2::new(
                vec![
                    partial_first_half(Real::zero(), quarter.clone()),
                    partial_first_half(quarter, three_quarters.clone()),
                    partial_first_half(three_quarters, Real::one()),
                    BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(second_half, &policy),
                    ),
                ],
                &policy,
            )
            .unwrap();
            let selected_region = CurveRegion2::try_new_with_loop_topology(
                vec![selected_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            let rational_boundary = CurveRegionBoundaryLoop2::new(
                rational_circle
                    .iter()
                    .cloned()
                    .map(|curve| BezierSplitFragment2::Materialized {
                        start: BezierParameter2::Exact(Real::zero()),
                        end: BezierParameter2::Exact(Real::one()),
                        curve: BezierSubcurve2::RationalQuadratic(curve),
                    })
                    .collect(),
                &policy,
            )
            .unwrap();
            let rational_region = CurveRegion2::try_new_with_loop_topology(
                vec![rational_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            let evidence = selected_region
                .intersect_region(&rational_region, &policy)
                .expect("selected-fiber circle overlaps must publish complete evidence")
                .into_value();
            assert!(evidence.blockers().is_empty());
            assert_eq!(evidence.overlaps().len(), 6);
            assert!(evidence.overlaps().iter().all(|overlap| {
                overlap.first_range().start().is_algebraic_cusp()
                    && overlap.second_range().start().is_selected_fiber()
                    && overlap.second_range().end().is_selected_fiber()
            }));

            let result = selected_region
                .boolean_regions(&rational_region, &policy)
                .expect("selected-fiber circle overlaps must complete Boolean topology")
                .into_value();
            assert!(!result.union().is_empty());
            assert!(!result.intersection().is_empty());
            assert!(result.difference().is_empty());
            assert!(result.xor().is_empty());
        }
    }

    #[test]
    fn selected_fiber_analytic_circle_overlaps_complete_region_booleans() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let support = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::new(half.clone(), Real::zero()),
            Point2::from_values(2, 0),
        )
        .parallel_left(Real::zero())
        .unwrap();
        let analytic_quarter = |start: Point2, control: Point2, end: Point2| {
            RationalBezier2::from(
                RationalQuadraticBezier2::try_new(
                    start,
                    control,
                    end,
                    Real::one(),
                    Real::one(),
                    Real::from(2_i8),
                )
                .unwrap(),
            )
            .parallel_left(Real::one())
            .unwrap()
        };
        let analytic_circle = [
            analytic_quarter(
                Point2::new(half.clone(), Real::from(2_i8)),
                Point2::new(half.clone() - Real::from(2_i8), Real::from(2_i8)),
                Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
            ),
            analytic_quarter(
                Point2::new(half.clone() - Real::from(2_i8), Real::zero()),
                Point2::new(half.clone() - Real::from(2_i8), Real::from(-2_i8)),
                Point2::new(half.clone(), Real::from(-2_i8)),
            ),
            analytic_quarter(
                Point2::new(half.clone(), Real::from(-2_i8)),
                Point2::new(&half + Real::from(2_i8), Real::from(-2_i8)),
                Point2::new(&half + Real::from(2_i8), Real::zero()),
            ),
            analytic_quarter(
                Point2::new(&half + Real::from(2_i8), Real::zero()),
                Point2::new(&half + Real::from(2_i8), Real::from(2_i8)),
                Point2::new(half.clone(), Real::from(2_i8)),
            ),
        ];

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(polynomial) =
                BezierParameterPolynomial::try_new_power_basis(
                    vec![-half.clone(), Real::one(), Real::one()],
                    &policy,
                )
                .unwrap()
            else {
                panic!("the selected-center polynomial must construct");
            };
            let Classification::Decided(interval) =
                BezierParameterInterval::try_new(Real::zero(), half.clone(), &policy).unwrap()
            else {
                panic!("the selected-center interval must construct");
            };
            let Classification::Decided(center_parameter) =
                BezierAlgebraicParameter2::try_isolate(polynomial, interval, &policy).unwrap()
            else {
                panic!("the selected center must isolate");
            };
            let Classification::Decided(Some(first_half)) =
                BezierAlgebraicCuspSemicircle2::from_selected_parallel_normal(
                    support.clone(),
                    BezierParameter2::Algebraic(center_parameter),
                    Real::one(),
                    false,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the algebraic selected circle must construct");
            };
            let second_half = first_half.complementary_half();
            let quarter = (Real::one() / Real::from(4_i8)).unwrap();
            let three_quarters = &half + &quarter;
            let partial_first_half = |start: Real, end: Real| {
                let Classification::Decided(fragment) =
                    BezierAlgebraicCuspSemicircleFragment2::try_new(
                        first_half.clone(),
                        BezierAlgebraicCuspSemicircleParameter2::Exact(start),
                        BezierAlgebraicCuspSemicircleParameter2::Exact(end),
                        false,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("the strict cusp partition must construct");
                };
                BezierSplitFragment2::AlgebraicCuspSemicircle(fragment)
            };
            let selected_boundary = CurveRegionBoundaryLoop2::new(
                vec![
                    partial_first_half(Real::zero(), quarter.clone()),
                    partial_first_half(quarter, three_quarters.clone()),
                    partial_first_half(three_quarters, Real::one()),
                    BezierSplitFragment2::AlgebraicCuspSemicircle(
                        BezierAlgebraicCuspSemicircleFragment2::full(second_half, &policy),
                    ),
                ],
                &policy,
            )
            .unwrap();
            let selected_region = CurveRegion2::try_new_with_loop_topology(
                vec![selected_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();
            let analytic_boundary = CurveRegionBoundaryLoop2::new(
                analytic_circle
                    .iter()
                    .cloned()
                    .map(|parallel| {
                        let Classification::Decided(fragment) = BezierParallelFragment2::try_new(
                            parallel,
                            BezierParameterRange2::new_validated(
                                BezierParameter2::Exact(Real::zero()),
                                BezierParameter2::Exact(Real::one()),
                            ),
                            &policy,
                        )
                        .unwrap() else {
                            panic!("the exact analytic quarter must remain regular");
                        };
                        BezierSplitFragment2::AnalyticParallel(fragment)
                    })
                    .collect(),
                &policy,
            )
            .unwrap();
            let analytic_region = CurveRegion2::try_new_with_loop_topology(
                vec![analytic_boundary],
                vec![CurveRegionLoopRole::Material],
                vec![FillRule::NonZero],
                vec![CurveBoundaryInteriorSide2::Left],
            )
            .unwrap();

            let evidence = selected_region
                .intersect_region(&analytic_region, &policy)
                .expect("selected-fiber analytic overlaps must publish complete evidence")
                .into_value();
            assert!(evidence.blockers().is_empty());
            assert_eq!(evidence.overlaps().len(), 6);
            assert!(evidence.overlaps().iter().all(|overlap| {
                overlap.first_range().start().is_algebraic_cusp()
                    && overlap.second_range().start().is_selected_fiber()
                    && overlap.second_range().end().is_selected_fiber()
            }));

            let result = selected_region
                .boolean_regions(&analytic_region, &policy)
                .expect("selected-fiber analytic overlaps must complete Boolean topology")
                .into_value();
            assert!(!result.union().is_empty());
            assert!(!result.intersection().is_empty());
            assert!(result.difference().is_empty());
            assert!(result.xor().is_empty());
        }
    }

    #[test]
    fn exact_parallel_similarity_transports_points_derivatives_and_structure() {
        let source = QuadraticBezier2::new(
            Point2::from_values(0, 0),
            Point2::from_values(1, 2),
            Point2::from_values(3, 1),
        );
        let distance = (Real::one() / Real::from(2_i8)).unwrap();
        let parallel = source.parallel_left(distance).unwrap();
        let transform = Similarity2::try_from_real_affine(
            Real::zero(),
            Real::from(-2_i8),
            Real::from(2_i8),
            Real::zero(),
            Real::from(5_i8),
            Real::from(-7_i8),
        )
        .unwrap();
        let transformed = parallel.transform_similarity(&transform).unwrap();
        assert_eq!(transformed.distance(), &Real::one());
        assert!(matches!(
            transformed.source(),
            BezierParallelSource2::Quadratic(_)
        ));

        let parameter = (Real::one() / Real::from(3_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(source_point) =
                parallel.point_at(&parameter, &policy).unwrap()
            else {
                panic!("source parallel point became uncertain");
            };
            let Classification::Decided(transformed_point) =
                transformed.point_at(&parameter, &policy).unwrap()
            else {
                panic!("transformed parallel point became uncertain");
            };
            assert_eq!(transformed_point, transform.transform_point(&source_point));

            let Classification::Decided(source_derivative) =
                parallel.derivative_at(&parameter, &policy).unwrap()
            else {
                panic!("source parallel derivative became uncertain");
            };
            let Classification::Decided(transformed_derivative) =
                transformed.derivative_at(&parameter, &policy).unwrap()
            else {
                panic!("transformed parallel derivative became uncertain");
            };
            assert_eq!(
                transformed_derivative.dx(),
                &(Real::from(-2_i8) * source_derivative.dy())
            );
            assert_eq!(
                transformed_derivative.dy(),
                &(Real::from(2_i8) * source_derivative.dx())
            );
        }

        let reconstructed = BezierParallel2::from_source(
            transformed.source().clone(),
            transformed.distance().clone(),
        );
        assert_eq!(reconstructed, transformed);
    }

    #[test]
    fn exact_parallel_reflection_negates_scaled_left_distance() {
        let source = QuadraticBezier2::from_line_segment(
            LineSeg2::try_new(Point2::from_values(0, 0), Point2::from_values(2, 0)).unwrap(),
        );
        let parallel = source.parallel_left(Real::from(2_i8)).unwrap();
        let reflection = Similarity2::try_from_real_affine(
            Real::from(-3_i8),
            Real::zero(),
            Real::zero(),
            Real::from(3_i8),
            Real::zero(),
            Real::zero(),
        )
        .unwrap();
        let transformed = parallel.transform_similarity(&reflection).unwrap();

        assert_eq!(transformed.distance(), &Real::from(-6_i8));
        let BezierParallelSource2::Quadratic(transformed_source) = transformed.source() else {
            panic!("quadratic source family changed under reflection");
        };
        assert!(transformed_source.retained_exact_line_image().is_some());
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let half = (Real::one() / Real::from(2_i8)).unwrap();
            let Classification::Decided(point) = parallel.point_at(&half, &policy).unwrap() else {
                panic!("source line parallel point became uncertain");
            };
            let Classification::Decided(transformed_point) =
                transformed.point_at(&half, &policy).unwrap()
            else {
                panic!("reflected line parallel point became uncertain");
            };
            assert_eq!(transformed_point, reflection.transform_point(&point));
        }
    }

    fn parameter_lift_map(
        numerator: Vec<Real>,
        denominator: Vec<Real>,
    ) -> CurveIntersectionParameterLiftMap {
        CurveIntersectionParameterLiftMap {
            cofactor_row: 0,
            numerator_coefficients: numerator,
            denominator_coefficients: denominator,
        }
    }

    fn rational_component_partition(
        map: &CurveIntersectionParameterLiftMap,
        derivative_numerator: &[Real],
        policy: &CurveContext,
    ) -> CurveResult<Classification<Option<RationalParameterComponentPartition>>> {
        let mut parameter_image_map = RationalParameterImageMap2::new(
            map.numerator_coefficients.clone(),
            map.denominator_coefficients.clone(),
            policy,
        );
        rational_parameter_component_domains(
            map,
            derivative_numerator,
            &mut parameter_image_map,
            policy,
        )
    }

    #[test]
    fn rational_component_domain_clips_increasing_and_decreasing_maps_exactly() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let increasing = parameter_lift_map(
                vec![Real::from(-1_i8), Real::from(4_i8)],
                vec![Real::from(2_i8)],
            );
            let derivative = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_derivative(&increasing.numerator_coefficients),
                    &increasing.denominator_coefficients,
                ),
                &polynomial_multiply(
                    &increasing.numerator_coefficients,
                    &polynomial_derivative(&increasing.denominator_coefficients),
                ),
            );
            let Classification::Decided(Some(increasing)) =
                rational_component_partition(&increasing, &derivative, &policy).unwrap()
            else {
                panic!("increasing rational map did not clip");
            };
            assert!(increasing.isolated_points.is_empty());
            let [(increasing, std::cmp::Ordering::Less)] = increasing.domains.as_slice() else {
                panic!("increasing map did not produce one increasing domain");
            };
            assert_eq!(
                increasing.retained_start.as_exact(),
                Some(&(Real::one() / Real::from(4_i8)).unwrap())
            );
            assert_eq!(
                increasing.retained_end.as_exact(),
                Some(&(Real::from(3_i8) / Real::from(4_i8)).unwrap())
            );
            assert_eq!(increasing.lifted_start.as_exact(), Some(&Real::zero()));
            assert_eq!(increasing.lifted_end.as_exact(), Some(&Real::one()));

            let decreasing = parameter_lift_map(
                vec![Real::from(3_i8), Real::from(-4_i8)],
                vec![Real::from(2_i8)],
            );
            let derivative = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_derivative(&decreasing.numerator_coefficients),
                    &decreasing.denominator_coefficients,
                ),
                &polynomial_multiply(
                    &decreasing.numerator_coefficients,
                    &polynomial_derivative(&decreasing.denominator_coefficients),
                ),
            );
            let Classification::Decided(Some(decreasing)) =
                rational_component_partition(&decreasing, &derivative, &policy).unwrap()
            else {
                panic!("decreasing rational map did not clip");
            };
            assert!(decreasing.isolated_points.is_empty());
            let [(decreasing, std::cmp::Ordering::Greater)] = decreasing.domains.as_slice() else {
                panic!("decreasing map did not produce one decreasing domain");
            };
            assert_eq!(
                decreasing.retained_start.as_exact(),
                Some(&(Real::one() / Real::from(4_i8)).unwrap())
            );
            assert_eq!(
                decreasing.retained_end.as_exact(),
                Some(&(Real::from(3_i8) / Real::from(4_i8)).unwrap())
            );
            assert_eq!(decreasing.lifted_start.as_exact(), Some(&Real::one()));
            assert_eq!(decreasing.lifted_end.as_exact(), Some(&Real::zero()));
        }
    }

    #[test]
    fn rational_component_monotonicity_allows_stationary_points_without_sign_reversal() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            // 8*((s-1/2)^3+1/2) = 3+6s-12s^2+8s^3 has a
            // positive derivative with one double zero at s=1/2.
            let map = parameter_lift_map(
                vec![
                    Real::from(3_i8),
                    Real::from(6_i8),
                    Real::from(-12_i8),
                    Real::from(8_i8),
                ],
                vec![Real::from(8_i8)],
            );
            let derivative_numerator = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_derivative(&map.numerator_coefficients),
                    &map.denominator_coefficients,
                ),
                &polynomial_multiply(
                    &map.numerator_coefficients,
                    &polynomial_derivative(&map.denominator_coefficients),
                ),
            );
            let Classification::Decided(Some(domains)) =
                rational_component_partition(&map, &derivative_numerator, &policy).unwrap()
            else {
                panic!("weakly monotone full-domain map was rejected");
            };
            assert!(domains.isolated_points.is_empty());
            let [(domain, std::cmp::Ordering::Less)] = domains.domains.as_slice() else {
                panic!("stationary increasing map was not merged into one domain");
            };
            assert_eq!(domain.retained_start.as_exact(), Some(&Real::zero()));
            assert_eq!(domain.retained_end.as_exact(), Some(&Real::one()));
        }
    }

    #[test]
    fn rational_component_domains_split_noninjective_and_pole_separated_maps() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let noninjective = parameter_lift_map(
                vec![Real::zero(), Real::from(4_i8), Real::from(-4_i8)],
                vec![Real::one()],
            );
            let derivative = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_derivative(&noninjective.numerator_coefficients),
                    &noninjective.denominator_coefficients,
                ),
                &polynomial_multiply(
                    &noninjective.numerator_coefficients,
                    &polynomial_derivative(&noninjective.denominator_coefficients),
                ),
            );
            let Classification::Decided(Some(domains)) =
                rational_component_partition(&noninjective, &derivative, &policy).unwrap()
            else {
                panic!("noninjective finite map did not partition");
            };
            let [
                (ascending, std::cmp::Ordering::Less),
                (descending, std::cmp::Ordering::Greater),
            ] = domains.domains.as_slice()
            else {
                panic!("noninjective map did not produce two oriented domains");
            };
            let half = (Real::one() / Real::from(2_i8)).unwrap();
            assert_eq!(ascending.retained_start.as_exact(), Some(&Real::zero()));
            assert_eq!(ascending.retained_end.as_exact(), Some(&half));
            assert_eq!(ascending.lifted_start.as_exact(), Some(&Real::zero()));
            assert_eq!(ascending.lifted_end.as_exact(), Some(&Real::one()));
            assert_eq!(descending.retained_start.as_exact(), Some(&half));
            assert_eq!(descending.retained_end.as_exact(), Some(&Real::one()));
            assert_eq!(descending.lifted_start.as_exact(), Some(&Real::one()));
            assert_eq!(descending.lifted_end.as_exact(), Some(&Real::zero()));

            let quarter = (Real::one() / Real::from(4_i8)).unwrap();
            let pole_split = parameter_lift_map(
                vec![-quarter.clone(), Real::one()],
                vec![Real::from(-1_i8), Real::from(2_i8)],
            );
            let derivative = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_derivative(&pole_split.numerator_coefficients),
                    &pole_split.denominator_coefficients,
                ),
                &polynomial_multiply(
                    &pole_split.numerator_coefficients,
                    &polynomial_derivative(&pole_split.denominator_coefficients),
                ),
            );
            let Classification::Decided(Some(domains)) =
                rational_component_partition(&pole_split, &derivative, &policy).unwrap()
            else {
                panic!("pole-separated finite branches did not partition");
            };
            let [
                (first, std::cmp::Ordering::Greater),
                (second, std::cmp::Ordering::Greater),
            ] = domains.domains.as_slice()
            else {
                panic!("pole-separated map did not retain both finite branches");
            };
            let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
            assert_eq!(first.retained_start.as_exact(), Some(&Real::zero()));
            assert_eq!(first.retained_end.as_exact(), Some(&quarter));
            assert_eq!(first.lifted_start.as_exact(), Some(&quarter));
            assert_eq!(first.lifted_end.as_exact(), Some(&Real::zero()));
            assert_eq!(second.retained_start.as_exact(), Some(&three_quarters));
            assert_eq!(second.retained_end.as_exact(), Some(&Real::one()));
            assert_eq!(second.lifted_start.as_exact(), Some(&Real::one()));
            assert_eq!(second.lifted_end.as_exact(), Some(&three_quarters));
        }
    }

    #[test]
    fn rational_component_domains_retain_isolated_closed_square_touches() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let tangent_touch = parameter_lift_map(
                vec![Real::from(-1_i8), Real::from(4_i8), Real::from(-4_i8)],
                vec![Real::one()],
            );
            let derivative = polynomial_subtract(
                &polynomial_multiply(
                    &polynomial_derivative(&tangent_touch.numerator_coefficients),
                    &tangent_touch.denominator_coefficients,
                ),
                &polynomial_multiply(
                    &tangent_touch.numerator_coefficients,
                    &polynomial_derivative(&tangent_touch.denominator_coefficients),
                ),
            );
            let Classification::Decided(Some(partition)) =
                rational_component_partition(&tangent_touch, &derivative, &policy).unwrap()
            else {
                panic!("isolated closed-square component touch was not partitioned");
            };
            assert!(partition.domains.is_empty());
            let [point] = partition.isolated_points.as_slice() else {
                panic!("isolated component touch was not retained exactly once");
            };
            assert_eq!(
                point.retained_parameter.as_exact(),
                Some(&(Real::one() / Real::from(2_i8)).unwrap())
            );
            assert_eq!(point.lifted_parameter.as_exact(), Some(&Real::zero()));
        }
    }

    #[test]
    fn rational_component_range_checks_reject_only_relevant_roots() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let quarter = BezierParameter2::Exact((Real::one() / Real::from(4_i8)).unwrap());
            let three_quarters =
                BezierParameter2::Exact((Real::from(3_i8) / Real::from(4_i8)).unwrap());
            assert_eq!(
                polynomial_is_rootless_on_parameter_range(
                    &[Real::from(-1_i8), Real::from(10_i8)],
                    &quarter,
                    &three_quarters,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(true)
            );
            assert_eq!(
                polynomial_is_rootless_on_parameter_range(
                    &[Real::from(-1_i8), Real::from(2_i8)],
                    &quarter,
                    &three_quarters,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(false)
            );
            let zero = BezierParameter2::Exact(Real::zero());
            let one = BezierParameter2::Exact(Real::one());
            assert_eq!(
                polynomial_is_rootless_on_parameter_range(
                    &[Real::from(-1_i8), Real::from(2_i8)],
                    &zero,
                    &one,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(false)
            );
        }
    }

    #[test]
    fn rational_component_certificate_replays_equations_branch_and_poles() {
        let identity_equation = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let identity = parameter_lift_map(vec![Real::zero(), Real::one()], vec![Real::one()]);
        let selected_branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let opposite_branch = BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]);
        let vanishing_branch =
            BivariatePolynomial::new(vec![vec![Real::from(-1_i8)], vec![Real::from(2_i8)]]);
        let pole_equation = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one()],
            vec![Real::from(-1_i8), Real::from(-2_i8)],
        ]);
        let pole_map = parameter_lift_map(
            vec![Real::zero(), Real::one()],
            vec![Real::one(), Real::from(-2_i8)],
        );

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let equations = [identity_equation.clone(), identity_equation.clone()];
            let Classification::Decided(Some(evidence)) = certify_rational_parameter_component_map(
                &equations,
                &selected_branch,
                CurveResultantParameter::First,
                &identity,
                &policy,
            )
            .unwrap() else {
                panic!("selected identity component was not certified");
            };
            assert!(evidence.selected_pairs().is_empty());
            let [overlap] = evidence.overlaps.as_ref() else {
                panic!("identity component did not produce exactly one overlap");
            };
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&Real::zero(), &Real::one()))
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&Real::zero(), &Real::one()))
            );
            assert!(overlap.includes_start());
            assert!(overlap.includes_end());
            let Classification::Decided(Some(opposite)) = certify_rational_parameter_component_map(
                &equations,
                &opposite_branch,
                CurveResultantParameter::First,
                &identity,
                &policy,
            )
            .unwrap() else {
                panic!("opposite component was not decided");
            };
            assert!(opposite.overlaps.is_empty());
            assert!(opposite.selected_pairs().is_empty());
            let Classification::Decided(Some(vanishing)) =
                certify_rational_parameter_component_map(
                    &equations,
                    &vanishing_branch,
                    CurveResultantParameter::First,
                    &identity,
                    &policy,
                )
                .unwrap()
            else {
                panic!("an isolated branch zero did not partition the rational component");
            };
            assert!(vanishing.selected_pairs().is_empty());
            assert_eq!(vanishing.excluded_pairs().len(), 1);
            let [overlap] = vanishing.overlaps.as_ref() else {
                panic!("the positive half of the rational component was not retained");
            };
            let half = (Real::one() / Real::from(2_i8)).unwrap();
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&half, &Real::one()))
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&half, &Real::one()))
            );
            assert!(!overlap.includes_start());
            assert!(overlap.includes_end());
            let Classification::Decided(Some(zero_branch)) =
                certify_rational_parameter_component_map(
                    &equations,
                    &identity_equation,
                    CurveResultantParameter::First,
                    &identity,
                    &policy,
                )
                .unwrap()
            else {
                panic!("an identically zero selected branch was not decided");
            };
            assert!(zero_branch.overlaps.is_empty());
            assert!(zero_branch.selected_pairs().is_empty());
            assert!(zero_branch.excluded_pairs().is_empty());

            let pole_equations = [pole_equation.clone(), pole_equation.clone()];
            let Classification::Decided(Some(evidence)) = certify_rational_parameter_component_map(
                &pole_equations,
                &selected_branch,
                CurveResultantParameter::First,
                &pole_map,
                &policy,
            )
            .unwrap() else {
                panic!("finite component domain before a pole was not retained");
            };
            assert!(evidence.selected_pairs().is_empty());
            let [overlap] = evidence.overlaps.as_ref() else {
                panic!("pole-split map did not produce one finite overlap");
            };
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&Real::zero(), &(Real::one() / Real::from(3_i8)).unwrap()))
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&Real::zero(), &Real::one()))
            );
        }
    }

    #[test]
    fn parallel_pair_component_selector_owns_a_selected_tangent_event() {
        let identity = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let tangent_cross = BivariatePolynomial::new(vec![vec![-half.clone()], vec![Real::one()]]);
        for (norm_residual, event_is_selected) in [(Real::from(-1_i8), true), (Real::one(), false)]
        {
            let system = BezierParallelPairEquationSystem2 {
                first_equation: identity.clone(),
                second_equation: identity.clone(),
                norm_equation: identity.clone(),
                first_projection: tangent_cross.clone(),
                second_projection: tangent_cross.clone(),
                tangent_cross: tangent_cross.clone(),
                tangent_dot: BivariatePolynomial::new(vec![vec![Real::one()]]),
                norm_residual: BivariatePolynomial::new(vec![vec![norm_residual]]),
                first_normal_projection: BivariatePolynomial::new(vec![vec![Real::one()]]),
                first_distance: Real::one(),
                second_distance: Real::one(),
                first_distance_sign: RealSign::Positive,
                second_distance_sign: RealSign::Positive,
                weight_sign: RealSign::Positive,
            };
            for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                let config = CurveIntersectionResultantConfig {
                    min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
                    max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
                };
                let Classification::Decided(Some(component)) =
                    parameter_component_system_with_selector(
                        &[identity.clone(), identity.clone()],
                        &ParameterComponentSelector2::ParallelPair {
                            system: &system,
                            unordered_self_pair: false,
                        },
                        &policy,
                        config,
                    )
                    .unwrap()
                else {
                    panic!("the selected pair component was not partitioned");
                };
                assert_eq!(component.overlaps.len(), 2);
                assert_eq!(
                    component.selected_pairs().len(),
                    usize::from(event_is_selected),
                );
                assert_eq!(
                    component.excluded_pairs().len(),
                    usize::from(!event_is_selected),
                );
                assert_eq!(component.overlaps[0].includes_end(), event_is_selected);
                assert_eq!(component.overlaps[1].includes_start(), event_is_selected);
                assert_eq!(
                    component.overlaps[0].first_range().end().as_exact(),
                    Some(&half),
                );
                assert_eq!(
                    component.overlaps[1].first_range().start().as_exact(),
                    Some(&half),
                );
            }
        }
    }

    #[test]
    fn parallel_self_component_selector_keeps_one_ordered_half() {
        let complement = BivariatePolynomial::new(vec![
            vec![Real::from(-1_i8), Real::one()],
            vec![Real::one()],
        ]);
        let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let system = BezierParallelPairEquationSystem2 {
            first_equation: complement.clone(),
            second_equation: complement.clone(),
            norm_equation: complement.clone(),
            first_projection: one.clone(),
            second_projection: one.clone(),
            tangent_cross: one.clone(),
            tangent_dot: one.clone(),
            norm_residual: one.clone(),
            first_normal_projection: one,
            first_distance: Real::one(),
            second_distance: Real::one(),
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_sign: RealSign::Positive,
        };
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let config = CurveIntersectionResultantConfig {
                min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
                max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
            };
            let Classification::Decided(Some(component)) =
                parameter_component_system_with_selector(
                    &[complement.clone(), complement.clone()],
                    &ParameterComponentSelector2::ParallelPair {
                        system: &system,
                        unordered_self_pair: true,
                    },
                    &policy,
                    config,
                )
                .unwrap()
            else {
                panic!("the symmetric self component was not ordered");
            };
            let [overlap] = component.overlaps.as_ref() else {
                panic!("one strict half of the self component must remain");
            };
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&Real::zero(), &half)),
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&Real::one(), &half)),
            );
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Reversed,
            );
            assert!(overlap.includes_start());
            assert!(!overlap.includes_end());
            assert!(component.selected_pairs().is_empty());
            assert_eq!(component.excluded_pairs().len(), 1);
        }
    }

    #[test]
    fn parallel_pair_selector_splits_a_reducible_boundary_factor() {
        // The first support 4u-t=0 is also the tangent/projection boundary.
        // The second support 4u+t-4=0 never meets that boundary on the
        // authored square. The remaining tangent-parallel predicates must be
        // allowed to select or reject the first support without preventing the
        // transverse second support from being certified.
        let boundary_component = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::from(4_i8)],
            vec![Real::from(-1_i8)],
        ]);
        let transverse_component = BivariatePolynomial::new(vec![
            vec![Real::from(-4_i8), Real::from(4_i8)],
            vec![Real::one()],
        ]);
        let component = bivariate_multiply(&boundary_component, &transverse_component);
        let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let negative_one = BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]);
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        for (second_distance, expected_overlaps) in [(Real::one(), 2), (Real::from(2_i8), 1)] {
            let system = BezierParallelPairEquationSystem2 {
                first_equation: component.clone(),
                second_equation: component.clone(),
                norm_equation: component.clone(),
                first_projection: boundary_component.clone(),
                second_projection: boundary_component.clone(),
                tangent_cross: boundary_component.clone(),
                tangent_dot: one.clone(),
                norm_residual: negative_one.clone(),
                first_normal_projection: one.clone(),
                first_distance: Real::one(),
                second_distance,
                first_distance_sign: RealSign::Positive,
                second_distance_sign: RealSign::Positive,
                weight_sign: RealSign::Positive,
            };
            for retained_parameter in [
                CurveResultantParameter::First,
                CurveResultantParameter::Second,
            ] {
                for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
                    let Classification::Decided(Some(evidence)) =
                        certify_regular_implicit_parameter_component_with_selector(
                            &component,
                            &ParameterComponentSelector2::ParallelPair {
                                system: &system,
                                unordered_self_pair: false,
                            },
                            retained_parameter,
                            &policy,
                            config,
                        )
                        .unwrap()
                    else {
                        panic!("the selector-boundary factor was not split exactly");
                    };
                    assert_eq!(evidence.overlaps.len(), expected_overlaps);
                    assert_eq!(evidence.component_overlaps.len(), expected_overlaps);
                    assert!(evidence.overlaps.iter().any(|overlap| {
                        overlap.orientation() == RationalBezierOverlapOrientation2::Reversed
                            && overlap.second_range().exact_endpoints()
                                == Some((
                                    &Real::one(),
                                    &(Real::from(3_i8) / Real::from(4_i8)).unwrap(),
                                ))
                    }));
                    if expected_overlaps == 2 {
                        assert!(evidence.overlaps.iter().any(|overlap| {
                            overlap.orientation() == RationalBezierOverlapOrientation2::Same
                                && overlap.second_range().exact_endpoints()
                                    == Some((
                                        &Real::zero(),
                                        &(Real::one() / Real::from(4_i8)).unwrap(),
                                    ))
                        }));
                    }
                }
            }
        }
    }

    #[test]
    fn incident_component_charts_clip_exact_regular_barriers() {
        let support_before_barriers = BivariatePolynomial::new(vec![
            vec![Real::one(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let support_beyond_barriers = BivariatePolynomial::new(vec![
            vec![Real::from(2_i8), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let system = BezierParallelPairEquationSystem2 {
            first_equation: support_before_barriers.clone(),
            second_equation: support_before_barriers.clone(),
            norm_equation: support_before_barriers.clone(),
            first_projection: one.clone(),
            second_projection: one.clone(),
            tangent_cross: one.clone(),
            tangent_dot: one.clone(),
            norm_residual: one.clone(),
            first_normal_projection: one,
            first_distance: Real::one(),
            second_distance: Real::one(),
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_sign: RealSign::Positive,
        };
        let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
        let second_barrier =
            BezierParameter2::Exact((Real::from(-1_i8) / Real::from(2_i8)).unwrap());
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let selected = selected_parameter_component_on_incident_domain(
                &support_before_barriers,
                &system,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                Some(&first_barrier),
                &Real::zero(),
                BezierParameterRayDirection2::Decreasing,
                Some(&second_barrier),
                &policy,
                config,
            )
            .unwrap();
            let Classification::Decided(selected) = selected else {
                panic!("the pre-barrier component was uncertain")
            };
            assert!(selected.positive_dimensional);
            let excluded = selected_parameter_component_on_incident_domain(
                &support_beyond_barriers,
                &system,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                Some(&first_barrier),
                &Real::zero(),
                BezierParameterRayDirection2::Decreasing,
                Some(&second_barrier),
                &policy,
                config,
            )
            .unwrap();
            let Classification::Decided(excluded) = excluded else {
                panic!("the post-barrier component was uncertain")
            };
            assert!(!excluded.positive_dimensional);
            assert!(excluded.selected_pairs.is_empty());

            let half = (Real::one() / Real::from(2_i8)).unwrap();
            for axis_support in [
                BivariatePolynomial::new(vec![vec![-half.clone()], vec![Real::one()]]),
                BivariatePolynomial::new(vec![vec![-half, Real::one()]]),
            ] {
                let axis_system = BezierParallelPairEquationSystem2 {
                    first_equation: axis_support.clone(),
                    second_equation: axis_support.clone(),
                    norm_equation: axis_support.clone(),
                    ..system.clone()
                };
                let axis_selection = selected_parameter_component_on_incident_domain(
                    &axis_support,
                    &axis_system,
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    Some(&first_barrier),
                    &Real::zero(),
                    BezierParameterRayDirection2::Decreasing,
                    Some(&second_barrier),
                    &policy,
                    config,
                )
                .unwrap();
                let Classification::Decided(axis_selection) = axis_selection else {
                    panic!("the axis-wide component was uncertain")
                };
                assert!(axis_selection.positive_dimensional);

                let axis_constraint = incident_parameter_constraint(
                    axis_support.clone(),
                    &axis_support,
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    Some(&first_barrier),
                    &Real::zero(),
                    BezierParameterRayDirection2::Decreasing,
                    Some(&second_barrier),
                    &policy,
                    config,
                )
                .unwrap();
                let Classification::Decided(axis_constraint) = axis_constraint else {
                    panic!("the axis-wide constraint was uncertain")
                };
                assert!(axis_constraint.component_support.is_some());
                assert!(axis_constraint.isolated_projection.is_none());
            }
        }
    }

    #[test]
    fn incident_component_charts_transport_an_isolated_selected_event() {
        let support = BivariatePolynomial::new(vec![
            vec![Real::one(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let tangent_cross = BivariatePolynomial::new(vec![
            vec![Real::from(-2_i8)],
            vec![Real::zero()],
            vec![Real::one()],
        ]);
        let opposite_projection = bivariate_scale(tangent_cross.clone(), &Real::from(-1_i8));
        let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let system = BezierParallelPairEquationSystem2 {
            first_equation: support.clone(),
            second_equation: support.clone(),
            norm_equation: support.clone(),
            first_projection: opposite_projection.clone(),
            second_projection: opposite_projection,
            tangent_cross: tangent_cross.clone(),
            tangent_dot: one.clone(),
            norm_residual: BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]),
            first_normal_projection: one,
            first_distance: Real::one(),
            second_distance: Real::one(),
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_sign: RealSign::Positive,
        };
        let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(selection) =
                selected_parameter_component_on_incident_domain(
                    &support,
                    &system,
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    Some(&first_barrier),
                    &Real::zero(),
                    BezierParameterRayDirection2::Decreasing,
                    None,
                    &policy,
                    config,
                )
                .unwrap()
            else {
                panic!("the isolated exterior selector event was uncertain")
            };
            assert!(!selection.positive_dimensional);
            let [pair] = selection.selected_pairs.as_slice() else {
                panic!("the isolated exterior selector event was not retained once")
            };
            assert_eq!(
                signed_bivariate_at_parameter_pair(
                    &support,
                    &pair.parallel_parameter,
                    &pair.other_parameter,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(RealSign::Zero),
            );
            assert_eq!(
                signed_bivariate_at_parameter_pair(
                    &tangent_cross,
                    &pair.parallel_parameter,
                    &pair.other_parameter,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(RealSign::Zero),
            );
            assert_eq!(
                pair.parallel_parameter
                    .cmp_by_refinement(&first_barrier, &policy)
                    .unwrap(),
                Classification::Decided(std::cmp::Ordering::Less),
            );
        }
    }

    #[test]
    fn incident_constraint_retains_isolated_roots_after_component_analysis() {
        let support = BivariatePolynomial::new(vec![
            vec![Real::one(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let five_quarters = (Real::from(5_i8) / Real::from(4_i8)).unwrap();
        let constraint =
            BivariatePolynomial::new(vec![vec![-five_quarters.clone()], vec![Real::one()]]);
        let first_barrier = BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(constraint) = incident_parameter_constraint(
                support.clone(),
                &constraint,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                Some(&first_barrier),
                &Real::zero(),
                BezierParameterRayDirection2::Decreasing,
                None,
                &policy,
                config,
            )
            .unwrap() else {
                panic!("the isolated incident constraint was uncertain");
            };
            assert!(constraint.component_support.is_none());
            let Some(projection) = constraint.isolated_projection else {
                panic!("the isolated source/component constraint was discarded");
            };
            let BezierParallelIntersectionCandidates2::Candidates {
                parallel_parameters,
                other_parameters,
            } = projection.candidates
            else {
                panic!("the isolated incident constraint was not projected");
            };
            assert_eq!(
                parallel_parameters,
                vec![BezierParameter2::Exact(five_quarters.clone())],
            );
            assert_eq!(
                other_parameters,
                vec![BezierParameter2::Exact(
                    (Real::one() / Real::from(4_i8)).unwrap(),
                )],
            );
        }
    }

    #[test]
    fn incident_pair_projection_accepts_a_non_source_radical_component() {
        let source = |height| {
            QuadraticBezier2::from_line_segment(
                LineSeg2::try_new(
                    Point2::new(Real::zero(), Real::from(height)),
                    Point2::new(Real::one(), Real::from(height)),
                )
                .unwrap(),
            )
            .parallel_left(Real::one())
            .unwrap()
        };
        let first = source(0);
        let second = source(4);
        let support = BivariatePolynomial::new(vec![
            vec![Real::one(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let one = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let system = BezierParallelPairEquationSystem2 {
            first_equation: support.clone(),
            second_equation: support.clone(),
            norm_equation: support,
            first_projection: one.clone(),
            second_projection: one.clone(),
            tangent_cross: one.clone(),
            tangent_dot: one.clone(),
            norm_residual: one.clone(),
            first_normal_projection: one,
            first_distance: Real::one(),
            second_distance: Real::one(),
            first_distance_sign: RealSign::Positive,
            second_distance_sign: RealSign::Positive,
            weight_sign: RealSign::Positive,
        };
        let excluded = Classification::Decided(CertifiedParallelSourceOverlap2::without_contacts(
            CertifiedParallelSourceOverlapKind2::Excluded,
        ));

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let projection = project_parallel_pair_without_components_with_incident_rays(
                &system,
                &first,
                &second,
                &excluded,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                None,
                &Real::zero(),
                BezierParameterRayDirection2::Decreasing,
                None,
                &policy,
            )
            .unwrap();
            assert!(matches!(
                projection,
                Some(BezierParallelPairIncidentProjection2::PositiveDimensional),
            ));

            let fixed_first = BivariatePolynomial::new(vec![
                vec![-(Real::one() / Real::from(2_i8)).unwrap()],
                vec![Real::one()],
            ]);
            let axis_system = BezierParallelPairEquationSystem2 {
                first_equation: fixed_first.clone(),
                second_equation: fixed_first.clone(),
                norm_equation: fixed_first,
                ..system.clone()
            };
            let axis_projection = project_parallel_pair_without_components_with_incident_rays(
                &axis_system,
                &first,
                &second,
                &excluded,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                None,
                &Real::zero(),
                BezierParameterRayDirection2::Decreasing,
                None,
                &policy,
            )
            .unwrap();
            assert!(matches!(
                axis_projection,
                Some(BezierParallelPairIncidentProjection2::PositiveDimensional),
            ));

            let tangent_cross = BivariatePolynomial::new(vec![
                vec![Real::from(-2_i8)],
                vec![Real::zero()],
                vec![Real::one()],
            ]);
            let opposite_projection = bivariate_scale(tangent_cross.clone(), &Real::from(-1_i8));
            let isolated_system = BezierParallelPairEquationSystem2 {
                first_projection: opposite_projection.clone(),
                second_projection: opposite_projection,
                tangent_cross,
                norm_residual: BivariatePolynomial::new(vec![vec![Real::from(-1_i8)]]),
                ..system.clone()
            };
            let first_barrier =
                BezierParameter2::Exact((Real::from(3_i8) / Real::from(2_i8)).unwrap());
            let Some(BezierParallelPairIncidentProjection2::Isolated(projection)) =
                project_parallel_pair_without_components_with_incident_rays(
                    &isolated_system,
                    &first,
                    &second,
                    &excluded,
                    &Real::one(),
                    BezierParameterRayDirection2::Increasing,
                    Some(&first_barrier),
                    &Real::zero(),
                    BezierParameterRayDirection2::Decreasing,
                    None,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the isolated selected component event was not projected")
            };
            let Some(component_projection) = projection.radical_component_projection else {
                panic!("the isolated component event lost its projection")
            };
            let [pair] = component_projection.component_pairs.as_ref() else {
                panic!("the isolated component event was not retained once")
            };
            assert_eq!(
                signed_bivariate_at_parameter_pair(
                    &isolated_system.tangent_cross,
                    &pair.parallel_parameter,
                    &pair.other_parameter,
                    &policy,
                )
                .unwrap(),
                Classification::Decided(RealSign::Zero),
            );
        }
    }

    #[test]
    fn incident_non_source_parallel_overlap_reaches_the_common_projection() {
        let line = |start_x: i8, height: i8, distance: i8| {
            QuadraticBezier2::from_line_segment(
                LineSeg2::try_new(
                    Point2::new(Real::from(start_x), Real::from(height)),
                    Point2::new(Real::from(start_x + 1), Real::from(height)),
                )
                .unwrap(),
            )
            .parallel_left(Real::from(distance))
            .unwrap()
        };
        // The sources are disjoint parallel lines, but their selected
        // parallels are the same line with exterior correspondence u=t-1.
        // This is a radical component, not a source-coordinate component.
        let first = line(0, 0, 1);
        let second = line(1, 2, -1);
        let excluded = Classification::Decided(CertifiedParallelSourceOverlap2::without_contacts(
            CertifiedParallelSourceOverlapKind2::Excluded,
        ));
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(system)) =
                parallel_pair_equation_system(&first, &second, false, &policy).unwrap()
            else {
                panic!("the incident non-source overlap lacked a pair system")
            };
            let projection = project_parallel_pair_without_components_with_incident_rays(
                &system,
                &first,
                &second,
                &excluded,
                &Real::one(),
                BezierParameterRayDirection2::Increasing,
                None,
                &Real::zero(),
                BezierParameterRayDirection2::Decreasing,
                None,
                &policy,
            )
            .unwrap();
            assert!(matches!(
                projection,
                Some(BezierParallelPairIncidentProjection2::PositiveDimensional),
            ));
            let Classification::Decided(incident) = first
                .parallel_intersections_with_incident_rays(
                    &second,
                    &incident_domain(
                        &first,
                        Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    ),
                    &incident_domain(
                        &second,
                        Real::zero(),
                        BezierParameterRayDirection2::Decreasing,
                        &policy,
                    ),
                    &policy,
                )
                .unwrap()
            else {
                panic!("the complete incident pair result was uncertain")
            };
            let (intersections, positive_dimensional) = incident.into_parts();
            assert!(intersections.is_complete());
            assert!(positive_dimensional);
        }
    }

    #[test]
    fn algebraic_incident_barrier_retains_its_exact_compact_root() {
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let irrational = (Real::from(2_i8)).sqrt().unwrap();
            for (constant, compact_polynomial) in [
                (
                    Real::from(2_i8),
                    vec![Real::one(), Real::from(-4_i8), Real::from(2_i8)],
                ),
                (
                    irrational.clone(),
                    vec![
                        Real::one() - &irrational,
                        Real::from(2_i8) * &irrational,
                        -irrational.clone(),
                    ],
                ),
            ] {
                let polynomial = match BezierParameterPolynomial::try_new_power_basis(
                    vec![-constant, Real::zero(), Real::one()],
                    &policy,
                )
                .unwrap()
                {
                    Classification::Decided(polynomial) => polynomial,
                    Classification::Uncertain(reason) => {
                        panic!("the barrier polynomial was uncertain: {reason:?}")
                    }
                };
                let barriers = match polynomial
                    .isolate_incident_ray_roots(
                        &Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    )
                    .unwrap()
                {
                    Classification::Decided(barriers) => barriers,
                    Classification::Uncertain(reason) => {
                        panic!("incident barrier isolation was uncertain: {reason:?}")
                    }
                };
                let [barrier] = barriers.as_slice() else {
                    panic!("the positive square root has one increasing incident root")
                };
                let compact = match barrier
                    .incident_ray_compact_parameter(
                        &Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    )
                    .unwrap()
                {
                    Classification::Decided(compact) => compact,
                    Classification::Uncertain(reason) => {
                        panic!("the compact barrier was uncertain: {reason:?}")
                    }
                };
                assert_eq!(
                    signed_coefficients_at_parameter(compact_polynomial, &compact, &policy)
                        .unwrap(),
                    Classification::Decided(RealSign::Zero),
                );
                let restored = match compact
                    .incident_ray_parameter(
                        &Real::one(),
                        BezierParameterRayDirection2::Increasing,
                        &policy,
                    )
                    .unwrap()
                {
                    Classification::Decided(restored) => restored,
                    Classification::Uncertain(reason) => {
                        panic!("the restored incident barrier was uncertain: {reason:?}")
                    }
                };
                assert_eq!(
                    restored.same_value(barrier, &policy).unwrap(),
                    Classification::Decided(true),
                );
            }
        }
    }

    #[test]
    fn nonlinear_parameter_component_maps_and_clips_its_exact_branch() {
        // u=t^2 is monotone on the authored square but is not an affine or
        // projective parameter correspondence.  Independent axis clipping
        // would therefore retain false overlaps.
        let fraction = |numerator: i8, denominator: i8| {
            (Real::from(numerator) / Real::from(denominator)).unwrap()
        };
        let mut square_root_parameters =
            algebraic_parameters(vec![-fraction(1, 2), Real::zero(), Real::one()]);
        let square_root_half = square_root_parameters
            .pop()
            .expect("sqrt(1/2) has one authored-domain root");
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let overlap = nonlinear_parameter_component_overlap_for_test(&policy);
            let Classification::Decided(Some(mapped)) = overlap
                .map_parameter(
                    CurveResultantParameter::First,
                    &BezierParameter2::Exact(fraction(1, 2)),
                    &policy,
                )
                .unwrap()
            else {
                panic!("the exact nonlinear forward map was not decided");
            };
            assert_eq!(mapped.as_exact(), Some(&fraction(1, 4)));
            let Classification::Decided(Some(mapped)) = overlap
                .map_parameter(
                    CurveResultantParameter::Second,
                    &BezierParameter2::Exact(fraction(1, 4)),
                    &policy,
                )
                .unwrap()
            else {
                panic!("the exact nonlinear inverse map was not decided");
            };
            assert_eq!(mapped.as_exact(), Some(&fraction(1, 2)));
            let Classification::Decided(Some(mapped)) = overlap
                .map_parameter(CurveResultantParameter::First, &square_root_half, &policy)
                .unwrap()
            else {
                panic!("the algebraic nonlinear forward map was not decided");
            };
            assert_eq!(mapped.as_exact(), Some(&fraction(1, 2)));

            let first = BezierParameterRange2::from_exact(fraction(1, 5), fraction(2, 5));
            let disjoint_second =
                BezierParameterRange2::from_exact(fraction(1, 2), fraction(7, 10));
            assert_eq!(
                overlap
                    .clipped_ranges(&first, &disjoint_second, &policy)
                    .unwrap(),
                Classification::Decided(None),
            );

            let first = BezierParameterRange2::from_exact(fraction(1, 4), fraction(3, 4));
            let second = BezierParameterRange2::from_exact(fraction(1, 16), fraction(1, 4));
            let Classification::Decided(Some((first, second))) =
                overlap.clipped_ranges(&first, &second, &policy).unwrap()
            else {
                panic!("the paired nonlinear subrange was not retained");
            };
            assert_eq!(
                first.exact_endpoints(),
                Some((&fraction(1, 4), &fraction(1, 2))),
            );
            assert_eq!(
                second.exact_endpoints(),
                Some((&fraction(1, 16), &fraction(1, 4))),
            );

            let BezierParameter2::Algebraic(retained_parameter) = square_root_half.clone() else {
                panic!("sqrt(1/2) was not retained algebraically")
            };
            let selected_parameter = |value: Real| {
                CurveRegionParameter2::from_selected_fiber(
                    BezierAlgebraicSelectedFiberAuthority2::exact_parameter(
                        retained_parameter.clone(),
                        value,
                        &policy,
                    ),
                )
            };
            let first = CurveRegionParameterRange2::new_validated(
                selected_parameter(fraction(1, 4)),
                selected_parameter(fraction(3, 4)),
            );
            let second = CurveRegionParameterRange2::from_bezier_range(
                BezierParameterRange2::from_exact(fraction(1, 16), fraction(1, 4)),
            );
            let Classification::Decided(Some((first, second))) = overlap
                .clipped_curve_region_ranges(&first, &second, &policy)
                .unwrap()
            else {
                panic!("the selected first-axis nonlinear subrange was not retained");
            };
            let first_start = first
                .start()
                .as_selected_fiber()
                .expect("an unchanged selected first bound must remain local");
            assert_eq!(
                first_start.order_to_real(&fraction(1, 4), &policy).unwrap(),
                Classification::Decided(std::cmp::Ordering::Equal),
            );
            assert_eq!(first.end().as_exact(), Some(&fraction(1, 2)));
            assert_eq!(
                second.exact_endpoints(),
                Some((&fraction(1, 16), &fraction(1, 4))),
            );

            let first = CurveRegionParameterRange2::from_bezier_range(
                BezierParameterRange2::from_exact(fraction(1, 4), fraction(3, 4)),
            );
            let second = CurveRegionParameterRange2::new_validated(
                selected_parameter(fraction(1, 16)),
                selected_parameter(fraction(1, 4)),
            );
            let Classification::Decided(Some((first, second))) = overlap
                .clipped_curve_region_ranges(&first, &second, &policy)
                .unwrap()
            else {
                panic!("the selected second-axis nonlinear subrange was not retained");
            };
            assert_eq!(first.start().as_exact(), Some(&fraction(1, 4)));
            assert_eq!(first.end().as_exact(), Some(&fraction(1, 2)));
            for (parameter, expected) in [
                (second.start(), fraction(1, 16)),
                (second.end(), fraction(1, 4)),
            ] {
                let selected = parameter
                    .as_selected_fiber()
                    .expect("an unchanged selected second bound must remain local");
                assert_eq!(
                    selected.order_to_real(&expected, &policy).unwrap(),
                    Classification::Decided(std::cmp::Ordering::Equal),
                );
            }
        }
    }

    #[test]
    fn non_source_parallel_overlap_replays_the_radical_component() {
        let line = |height: i8| {
            QuadraticBezier2::from_line_segment(
                LineSeg2::try_new(
                    Point2::new(Real::zero(), Real::from(height)),
                    Point2::new(Real::one(), Real::from(height)),
                )
                .unwrap(),
            )
        };
        let first = line(0).parallel_left(Real::one()).unwrap();
        let second = line(2).parallel_left(Real::from(-1_i8)).unwrap();
        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(system)) =
                parallel_pair_equation_system(&first, &second, true, &policy).unwrap()
            else {
                panic!("the coincident parallel lines must reach their exact pair system");
            };
            let Classification::Decided(projection) =
                project_parallel_pair_intersection_system(&system, &first, &second, None, &policy)
                    .unwrap()
            else {
                panic!("the non-source radical component was not projected");
            };
            let Classification::Decided(intersections) = first
                .replay_parallel_pair_projection(&second, &system, projection, false, &policy)
                .unwrap()
            else {
                panic!("the non-source radical component was not replayed");
            };
            assert!(intersections.is_complete());
            assert!(intersections.contacts().is_empty());
            let [overlap] = intersections.overlaps() else {
                panic!("the coincident selected lines must publish one overlap");
            };
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&Real::zero(), &Real::one())),
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&Real::zero(), &Real::one())),
            );
            assert!(overlap.includes_start());
            assert!(overlap.includes_end());
            assert_eq!(intersections.component_overlaps().len(), 1);
        }
    }

    #[test]
    fn rational_component_partitions_odd_even_and_endpoint_branch_zeros() {
        let identity_equation = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let identity = parameter_lift_map(vec![Real::zero(), Real::one()], vec![Real::one()]);
        let punctured_branch =
            BivariatePolynomial::new(vec![vec![Real::one(), Real::from(-4_i8), Real::from(4_i8)]]);
        let start_branch = BivariatePolynomial::new(vec![vec![Real::zero(), Real::one()]]);
        let end_branch = BivariatePolynomial::new(vec![vec![Real::one(), Real::from(-1_i8)]]);
        let negative_punctured_branch = BivariatePolynomial::new(vec![vec![
            Real::from(-1_i8),
            Real::from(4_i8),
            Real::from(-4_i8),
        ]]);
        let reversed_equation = BivariatePolynomial::new(vec![
            vec![Real::from(-1_i8), Real::one()],
            vec![Real::one()],
        ]);
        let reversed = parameter_lift_map(vec![Real::one(), Real::from(-1_i8)], vec![Real::one()]);
        let crossing_branch = BivariatePolynomial::new(vec![vec![
            (Real::from(-1_i8) / Real::from(2_i8)).unwrap(),
            Real::one(),
        ]]);
        let zero = Real::zero();
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let one = Real::one();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let equations = [identity_equation.clone(), identity_equation.clone()];
            let Classification::Decided(Some(punctured)) =
                certify_rational_parameter_component_map(
                    &equations,
                    &punctured_branch,
                    CurveResultantParameter::First,
                    &identity,
                    &policy,
                )
                .unwrap()
            else {
                panic!("an even branch zero did not partition the rational component");
            };
            assert!(punctured.selected_pairs().is_empty());
            assert_eq!(punctured.excluded_pairs().len(), 1);
            let [before, after] = punctured.overlaps.as_ref() else {
                panic!("an interior puncture must produce two open-sided overlaps");
            };
            assert_eq!(before.first_range().exact_endpoints(), Some((&zero, &half)));
            assert_eq!(after.first_range().exact_endpoints(), Some((&half, &one)));
            assert!(before.includes_start());
            assert!(!before.includes_end());
            assert!(!after.includes_start());
            assert!(after.includes_end());

            for (branch, expected_inclusion) in
                [(&start_branch, [false, true]), (&end_branch, [true, false])]
            {
                let Classification::Decided(Some(endpoint)) =
                    certify_rational_parameter_component_map(
                        &equations,
                        branch,
                        CurveResultantParameter::First,
                        &identity,
                        &policy,
                    )
                    .unwrap()
                else {
                    panic!("an endpoint branch zero was not retained as an open boundary");
                };
                assert_eq!(endpoint.excluded_pairs().len(), 1);
                let [overlap] = endpoint.overlaps.as_ref() else {
                    panic!("an endpoint branch zero must retain one positive-length overlap");
                };
                assert_eq!(
                    [overlap.includes_start(), overlap.includes_end()],
                    expected_inclusion
                );
            }

            let Classification::Decided(Some(negative)) = certify_rational_parameter_component_map(
                &equations,
                &negative_punctured_branch,
                CurveResultantParameter::First,
                &identity,
                &policy,
            )
            .unwrap() else {
                panic!("the negative punctured branch was not decided");
            };
            assert!(negative.overlaps.is_empty());
            assert!(negative.selected_pairs().is_empty());
            assert_eq!(negative.excluded_pairs().len(), 1);

            let reversed_equations = [reversed_equation.clone(), reversed_equation.clone()];
            let Classification::Decided(Some(reversed_evidence)) =
                certify_rational_parameter_component_map(
                    &reversed_equations,
                    &crossing_branch,
                    CurveResultantParameter::Second,
                    &reversed,
                    &policy,
                )
                .unwrap()
            else {
                panic!("the reversed branch-zero domain was not certified");
            };
            assert_eq!(reversed_evidence.excluded_pairs().len(), 1);
            let [overlap] = reversed_evidence.overlaps.as_ref() else {
                panic!("the reversed branch-zero domain must produce one overlap");
            };
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&zero, &half))
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&one, &half))
            );
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Reversed
            );
            assert!(overlap.includes_start());
            assert!(!overlap.includes_end());
        }
    }

    #[test]
    fn rational_component_system_discards_only_the_identically_zero_branch() {
        let zero_branch = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let selected = BivariatePolynomial::new(vec![
            vec![-quarter.clone(), Real::one()],
            vec![Real::from(-1_i8)],
        ]);
        let component = bivariate_multiply(&zero_branch, &selected);
        let equations = [
            bivariate_multiply(
                &component,
                &BivariatePolynomial::new(vec![vec![Real::from(2_i8)], vec![Real::one()]]),
            ),
            bivariate_multiply(
                &component,
                &BivariatePolynomial::new(vec![vec![Real::from(3_i8), Real::one()]]),
            ),
        ];
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };
        let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(system)) =
                parameter_component_system(&equations, &zero_branch, &policy, config).unwrap()
            else {
                panic!("the residual selected component was not transported");
            };
            assert!(system.selected_pairs().is_empty());
            let [overlap] = system.overlaps.as_ref() else {
                panic!("only the positive shifted component may survive");
            };
            assert_eq!(
                overlap.first_range().exact_endpoints(),
                Some((&Real::zero(), &three_quarters))
            );
            assert_eq!(
                overlap.second_range().exact_endpoints(),
                Some((&quarter, &Real::one()))
            );
            assert_eq!(
                overlap.orientation(),
                RationalBezierOverlapOrientation2::Same
            );
        }
    }

    #[test]
    fn rational_component_system_retains_residual_isolated_candidates() {
        let quarter = (Real::one() / Real::from(4_i8)).unwrap();
        let three_quarters = (Real::from(3_i8) / Real::from(4_i8)).unwrap();
        let component = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::from(-1_i8)],
            vec![Real::one()],
        ]);
        let first_residual =
            BivariatePolynomial::new(vec![vec![-quarter.clone()], vec![Real::one()]]);
        let second_residual =
            BivariatePolynomial::new(vec![vec![-three_quarters.clone(), Real::one()]]);
        let equations = [
            bivariate_multiply(&component, &first_residual),
            bivariate_multiply(&component, &second_residual),
        ];
        let branch = BivariatePolynomial::new(vec![vec![Real::one()]]);
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(system)) =
                parameter_component_system(&equations, &branch, &policy, config).unwrap()
            else {
                panic!("shared component plus residual point was not decomposed");
            };
            assert_eq!(system.overlaps.len(), 1);
            let Classification::Decided(BezierParallelIntersectionCandidates2::Candidates {
                parallel_parameters,
                other_parameters,
            }) = project_parallel_intersection_system(
                &system.residual_equations[0],
                &system.residual_equations[1],
                &policy,
            )
            .unwrap()
            else {
                panic!("residual isolated solution was discarded");
            };
            assert_eq!(
                parallel_parameters,
                vec![BezierParameter2::Exact(quarter.clone())]
            );
            assert_eq!(
                other_parameters,
                vec![BezierParameter2::Exact(three_quarters.clone())]
            );
        }
    }

    #[test]
    fn branch_zero_component_pair_suppresses_the_same_residual_candidate() {
        let half = (Real::one() / Real::from(2_i8)).unwrap();
        let component = BivariatePolynomial::new(vec![
            vec![Real::zero(), Real::from(-1_i8)],
            vec![Real::one()],
        ]);
        let first_residual = BivariatePolynomial::new(vec![vec![-half.clone()], vec![Real::one()]]);
        let second_residual = BivariatePolynomial::new(vec![vec![-half.clone(), Real::one()]]);
        let equations = [
            bivariate_multiply(&component, &first_residual),
            bivariate_multiply(&component, &second_residual),
        ];
        let branch = BivariatePolynomial::new(vec![vec![
            Real::from(-1_i8),
            Real::from(4_i8),
            Real::from(-4_i8),
        ]]);
        let config = CurveIntersectionResultantConfig {
            min_precision: PARALLEL_INTERSECTION_RESULTANT_PRECISION,
            max_resultant_degree: MAX_PARALLEL_INTERSECTION_RESULTANT_DEGREE,
        };

        for policy in [CurveContext::STRICT, CurveContext::APPROXIMATE_512] {
            let Classification::Decided(Some(system)) =
                parameter_component_system(&equations, &branch, &policy, config).unwrap()
            else {
                panic!("the branch-zero residual coincidence was not decomposed");
            };
            assert!(system.overlaps.is_empty());
            assert!(system.selected_pairs().is_empty());
            let [excluded] = system.excluded_pairs() else {
                panic!("the strict branch zero was not retained as exclusion evidence");
            };
            assert!(
                excluded
                    == &BezierParallelIntersectionParameterPair2 {
                        parallel_parameter: BezierParameter2::Exact(half.clone()),
                        other_parameter: BezierParameter2::Exact(half.clone()),
                    },
                "the excluded component pair changed"
            );

            let Classification::Decided(candidate_system) =
                parallel_candidate_system_from_parameter_components(system, &policy).unwrap()
            else {
                panic!("the residual candidate projection was undecidable");
            };
            let BezierParallelIntersectionCandidates2::Candidates {
                parallel_parameters,
                other_parameters,
            } = &candidate_system.candidates
            else {
                panic!("the residual branch-zero pair was not projected");
            };
            assert_eq!(
                parallel_parameters,
                &[BezierParameter2::Exact(half.clone())]
            );
            assert_eq!(other_parameters, &[BezierParameter2::Exact(half.clone())]);
            assert!(matches!(
                parallel_parameter_pair_is_excluded(
                    &candidate_system.component_pairs
                        [candidate_system.selected_component_pair_count..],
                    &parallel_parameters[0],
                    &other_parameters[0],
                    &policy,
                )
                .unwrap(),
                Classification::Decided(true)
            ));
        }
    }

